(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-1019",module:"changshi",prompt:"根据我国宪法，国家主席必须年满多少周岁？",options:["35周岁", "40周岁", "45周岁", "50周岁"],answer:2,explanation:"宪法规定，有选举权和被选举权的年满四十五周岁的中国公民可以被选为国家主席、副主席。"},{id:"cs-1020",module:"changshi",prompt:"我国宪法规定，有权决定全国总动员的是：",options:["国务院", "中央军委", "全国人大常委会", "国防部"],answer:2,explanation:"全国人大常委会在全国人大闭会期间有权决定全国总动员或局部总动员；国家主席根据人大决定发布动员令。"},{id:"cs-1021",module:"changshi",prompt:"我国宪法规定，批准省、自治区、直辖市的建置属于：",options:["国务院", "全国人大", "全国人大常委会", "民政部"],answer:1,explanation:"省、自治区、直辖市的建置由全国人民代表大会批准；县、市的建置由国务院批准。"},{id:"cs-1022",module:"changshi",prompt:"我国宪法规定，国务院总理人选由谁提名？",options:["全国人大主席团", "国家主席", "中共中央", "全国人大常委会"],answer:1,explanation:"根据宪法，国务院总理人选由国家主席向全国人民代表大会提名，由全国人大决定并任命。"},{id:"cs-1023",module:"changshi",prompt:"我国宪法规定，乡、民族乡、镇的人民代表大会每届任期：",options:["3年", "4年", "5年", "6年"],answer:2,explanation:"2018年宪法修正案后，地方各级人民代表大会每届任期统一为五年。"},{id:"cs-1024",module:"changshi",prompt:"我国宪法规定，监察委员会主任每届任期同本级人大每届任期相同，国家监察委员会主任连续任职不得超过：",options:["一届", "两届", "三届", "不限"],answer:1,explanation:"国家监察委员会主任连续任职不得超过两届，与最高人民法院院长、最高人民检察院检察长相同。"},{id:"cs-1025",module:"changshi",prompt:"我国宪法规定，全国人大有权罢免：",options:["任何公民", "国家主席、国务院总理等国家机关领导人员", "基层村干部", "企业负责人"],answer:1,explanation:"全国人大有权罢免国家主席、副主席、国务院组成人员、中央军委组成人员等国家机关领导人员。"},{id:"cs-1026",module:"changshi",prompt:"我国宪法规定，特别行政区立法机关制定的法律须报：",options:["国务院备案", "全国人大常委会备案", "最高人民法院备案", "中联办备案"],answer:1,explanation:"特别行政区立法机关制定的法律须报全国人民代表大会常务委员会备案，备案不影响法律的生效。"},{id:"cs-1027",module:"changshi",prompt:"我国宪法规定，人民法院审理案件，除法律规定的特别情况外：",options:["一律不公开进行", "一律公开进行", "由院长决定是否公开", "由当事人选择"],answer:1,explanation:"宪法规定人民法院审理案件除法律规定的特别情况外，一律公开进行，被告人有权获得辩护。"},{id:"cs-1028",module:"changshi",prompt:"我国宪法规定，居民委员会和村民委员会是：",options:["国家行政机关", "基层群众性自治组织", "司法机关", "派出机构"],answer:1,explanation:"居委会和村委会是基层群众性自治组织，不是一级政府或行政机关。"},{id:"cs-1029",module:"changshi",prompt:"我国宪法规定，国家工作人员就职时应当依照法律规定：",options:["向党旗宣誓", "公开进行宪法宣誓", "宣读任职承诺", "接受人大质询"],answer:1,explanation:"宪法宣誓制度：国家工作人员就职时应当依照法律规定公开进行宪法宣誓。"},{id:"cs-1030",module:"changshi",prompt:"我国宪法规定，公民在法律面前一律平等，这里的平等是指：",options:["结果完全相同", "法律适用上的平等", "经济地位平等", "收入分配平均"],answer:1,explanation:"法律面前人人平等指法律适用上的平等，即任何人违法都同样受法律追究，不指结果或经济平等。"},{id:"cs-1031",module:"changshi",prompt:"我国宪法规定，国家为了公共利益的需要，可以依照法律规定对土地实行：",options:["无偿占有", "征收或者征用并给予补偿", "直接划拨", "强制买卖"],answer:1,explanation:"宪法规定国家为了公共利益的需要，可以依照法律规定对土地实行征收或者征用并给予补偿。"},{id:"cs-1032",module:"changshi",prompt:"我国宪法规定，中华人民共和国公民有宗教信仰自由，任何国家机关不得：",options:["管理宗教事务", "强制公民信仰宗教或者不信仰宗教", "宣传无神论", "批准宗教场所"],answer:1,explanation:"宪法规定任何人不得强制公民信仰宗教或者不信仰宗教，不得歧视信仰宗教的公民和不信仰宗教的公民。"},{id:"cs-1033",module:"changshi",prompt:"我国宪法规定，全国人大常委会的组成人员不得担任：",options:["大学教授", "国家行政机关、监察机关、审判机关和检察机关的职务", "政协委员", "律师协会会员"],answer:1,explanation:"全国人大常委会组成人员不得担任国家行政机关、监察机关、审判机关和检察机关的职务，以保证监督独立性。"},{id:"cs-1034",module:"changshi",prompt:"根据民法典，八周岁以上的未成年人是：",options:["无民事行为能力人", "限制民事行为能力人", "完全民事行为能力人", "视情况认定"],answer:1,explanation:"八周岁以上未成年人为限制民事行为能力人，可独立实施纯获利益的或与其年龄智力相适应的行为。"},{id:"cs-1035",module:"changshi",prompt:"根据民法典，不满八周岁的未成年人实施的民事法律行为：",options:["一律有效", "由其法定代理人代理实施", "经追认后有效", "部分有效"],answer:1,explanation:"不满八周岁为无民事行为能力人，须由法定代理人代理实施民事法律行为。"},{id:"cs-1036",module:"changshi",prompt:"根据民法典，普通诉讼时效期间为：",options:["一年", "二年", "三年", "五年"],answer:2,explanation:"民法典规定向人民法院请求保护民事权利的诉讼时效期间为三年，自权利人知道或应当知道权利受损及义务人之日起算。"},{id:"cs-1037",module:"changshi",prompt:"根据民法典，因不可抗力不能履行合同的：",options:["一律免除责任", "根据不可抗力的影响部分或全部免除责任", "必须继续履行", "自动解除合同"],answer:1,explanation:"因不可抗力不能履行合同的，根据不可抗力的影响部分或者全部免除责任，但应及时通知对方。"},{id:"cs-1038",module:"changshi",prompt:"根据民法典，无处分权人将财产转让给第三人，受让人符合善意取得条件的：",options:["原所有权人可追回", "受让人取得所有权", "合同无效", "转让自动撤销"],answer:1,explanation:"善意取得的要件：受让人善意、支付合理价格、已登记或交付，符合条件则取得所有权，原所有权人只能向无处分权人追偿。"},{id:"cs-1039",module:"changshi",prompt:"根据民法典，居住权自何时设立？",options:["合同签订时", "登记时", "交付房屋时", "支付价款时"],answer:1,explanation:"居住权自登记时设立，居住权无偿设立为原则，不得转让、继承。"},{id:"cs-1040",module:"changshi",prompt:"根据民法典，遗嘱的形式不包括：",options:["自书遗嘱", "代书遗嘱", "口头遗嘱", "网络遗嘱"],answer:3,explanation:"民法典规定的遗嘱形式有自书、代书、打印、录音录像、口头（危急情况）和公证遗嘱，没有网络遗嘱。"},{id:"cs-1041",module:"changshi",prompt:"根据民法典，代书遗嘱需要：",options:["一名见证人即可", "两名以上见证人在场见证", "公证后生效", "全体继承人同意"],answer:1,explanation:"代书遗嘱应当有两个以上见证人在场见证，由其中一人代书，并由遗嘱人、代书人和其他见证人签名。"},{id:"cs-1042",module:"changshi",prompt:"根据民法典，限制民事行为能力人订立的纯获利益的合同：",options:["无效", "有效", "效力待定", "可撤销"],answer:1,explanation:"限制民事行为能力人实施的纯获利益的民事法律行为或者与其年龄、智力相适应的行为有效。"},{id:"cs-1043",module:"changshi",prompt:"根据民法典，人格权受到侵害的，受害人有权请求：",options:["只能请求赔偿损失", "精神损害赔偿或停止侵害等救济", "只能赔礼道歉", "只能刑事立案"],answer:1,explanation:"人格权受侵害的，受害人可请求行为人停止侵害、消除影响、赔礼道歉、赔偿损失等，不要求以实际损失为前提。"},{id:"cs-1044",module:"changshi",prompt:"根据民法典，建筑物区分所有权中，业主对专有部分：",options:["可任意拆改", "享有占有、使用、收益和处分的权利", "只能自住", "不得出租"],answer:1,explanation:"业主对建筑物内的住宅、经营性用房等专有部分享有占有、使用、收益和处分的权利，但不得危及建筑物安全。"},{id:"cs-1045",module:"changshi",prompt:"根据民法典，当事人约定不得转让的债权，债权人转让债权的：",options:["转让有效", "该约定不得对抗善意第三人", "转让无效", "需债务人同意"],answer:1,explanation:"当事人约定非金钱债权不得转让的，不得对抗善意第三人；金钱债权不得转让的约定不得对抗第三人。"},{id:"cs-1046",module:"changshi",prompt:"根据民法典，保证方式没有约定或约定不明确的，按照：",options:["一般保证承担保证责任", "连带责任保证承担", "保证人自选", "无效"],answer:0,explanation:"民法典规定当事人在保证合同中对保证方式没有约定或者约定不明确的，按照一般保证承担保证责任。"},{id:"cs-1047",module:"changshi",prompt:"根据民法典，自权利受到损害之日起超过多少年的，人民法院不予保护（最长保护期）？",options:["十年", "十五年", "二十年", "三十年"],answer:2,explanation:"诉讼时效最长保护期为二十年，自权利受到损害之日起计算，特殊情况可申请延长。"},{id:"cs-1048",module:"changshi",prompt:"根据刑法，已满十四周岁不满十六周岁的人，应负刑事责任的行为不包括：",options:["故意杀人", "故意伤害致人重伤", "盗窃", "抢劫"],answer:2,explanation:"已满十四不满十六周岁只对故意杀人、故意伤害致人重伤或死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投放危险物质八类行为负刑事责任，盗窃不在其中。"},{id:"cs-1049",module:"changshi",prompt:"根据刑法，正当防卫明显超过必要限度造成重大损害的：",options:["不负刑事责任", "应当负刑事责任，但应当减轻或者免除处罚", "按故意伤害从重处罚", "属于故意犯罪"],answer:1,explanation:"正当防卫明显超过必要限度造成重大损害的，是防卫过当，应当负刑事责任，但应当减轻或者免除处罚。"},{id:"cs-1050",module:"changshi",prompt:"根据刑法，对正在进行的行凶、杀人等严重危及人身安全的暴力犯罪采取防卫行为造成不法侵害人伤亡的：",options:["属于防卫过当", "不属于防卫过当，不负刑事责任", "需承担民事赔偿", "应减轻处罚"],answer:1,explanation:"刑法第二十条第三款（特殊防卫）：对严重危及人身安全的暴力犯罪采取防卫致不法侵害人伤亡的，不属于防卫过当，不负刑事责任。"},{id:"cs-1051",module:"changshi",prompt:"根据刑法，犯罪预备与犯罪未遂的根本区别在于：",options:["是否着手实行犯罪", "是否既遂", "主观故意内容", "犯罪动机"],answer:0,explanation:"犯罪预备是尚未着手实行犯罪，为犯罪准备工具、制造条件；已经着手实行而未得逞的是犯罪未遂。"},{id:"cs-1052",module:"changshi",prompt:"根据刑法，犯罪中止的成立要件是：",options:["自动放弃犯罪或自动有效地防止犯罪结果发生", "被他人制止", "意志以外的原因未得逞", "犯罪未被发现"],answer:0,explanation:"在犯罪过程中自动放弃犯罪或者自动有效地防止犯罪结果发生的，是犯罪中止；没有造成损害的应当免除处罚。"},{id:"cs-1053",module:"changshi",prompt:"根据刑法，管制的期限为：",options:["三个月以上一年以下", "三个月以上二年以下", "六个月以上二年以下", "一年以上三年以下"],answer:1,explanation:"管制的期限为三个月以上二年以下，由社区矫正机构执行，不剥夺人身自由。"},{id:"cs-1054",module:"changshi",prompt:"根据刑法，拘役的期限为：",options:["一个月以上六个月以下", "十五日以上三个月以下", "三个月以上一年以下", "六个月以上一年以下"],answer:0,explanation:"拘役的期限为一个月以上六个月以下，数罪并罚时不得超过一年。"},{id:"cs-1055",module:"changshi",prompt:"根据刑法，有期徒刑数罪并罚的最高刑期不得超过：",options:["十五年", "二十年", "二十五年", "三十年"],answer:2,explanation:"数罪并罚时，有期徒刑总和刑期不满三十五年的，最高不超过二十年；总和刑期在三十五年以上的，最高不超过二十五年。"},{id:"cs-1056",module:"changshi",prompt:"根据刑法，缓刑的适用对象是被判处：",options:["无期徒刑的犯罪分子", "拘役、三年以下有期徒刑的犯罪分子", "管制刑的犯罪分子", "死刑缓期执行的犯罪分子"],answer:1,explanation:"缓刑适用于被判处拘役或三年以下有期徒刑，同时符合犯罪情节较轻、有悔罪表现等条件的犯罪分子。"},{id:"cs-1057",module:"changshi",prompt:"根据刑法，累犯的成立要件之一是前后罪均被判处：",options:["拘役", "管制", "有期徒刑以上刑罚", "罚金"],answer:2,explanation:"一般累犯要求前后罪均被判处有期徒刑以上刑罚，且后罪发生在前罪刑罚执行完毕或赦免后五年以内。"},{id:"cs-1058",module:"changshi",prompt:"根据刑法，自首的成立要件是：",options:["如实供述自己的罪行", "主动投案并如实供述自己的罪行", "认罪认罚", "赔偿被害人损失"],answer:1,explanation:"自首是指犯罪以后自动投案，如实供述自己的罪行；如实供述是自首的必要条件。"},{id:"cs-1059",module:"changshi",prompt:"根据刑法，立功的表现不包括：",options:["检举他人犯罪查证属实", "提供重要线索得以侦破其他案件", "阻止他人犯罪活动", "如实供述自己的罪行"],answer:3,explanation:"立功指揭发他人犯罪、提供重要线索等；如实供述自己的罪行属于自首的构成要件，不是立功。"},{id:"cs-1060",module:"changshi",prompt:"根据行政处罚法，限制人身自由的行政处罚只能由：",options:["公安机关和司法机关", "公安机关和法律规定的其他机关", "任何行政机关", "法院"],answer:1,explanation:"限制人身自由的行政处罚权只能由公安机关和法律规定的其他机关行使，且只能由法律设定。"},{id:"cs-1061",module:"changshi",prompt:"根据行政处罚法，罚款属于：",options:["行政强制措施", "行政处罚", "行政处分", "刑事处罚"],answer:1,explanation:"罚款是行政处罚的一种；行政处分是对公务员的内部惩戒，二者性质不同。"},{id:"cs-1062",module:"changshi",prompt:"根据行政许可法，行政许可原则上由：",options:["行政机关依申请作出", "法院判决", "人大决定", "自动取得"],answer:0,explanation:"行政许可是依申请的行政行为，需行政相对人提出申请，行政机关审查后作出决定。"},{id:"cs-1063",module:"changshi",prompt:"根据国家赔偿法，行政赔偿的责任主体是：",options:["国家，由赔偿义务机关履行", "具体工作人员个人", "行政机关负责人", "财政部门"],answer:0,explanation:"国家赔偿的责任主体是国家，由赔偿义务机关代表国家履行赔偿义务，赔偿费用列入财政预算。"},{id:"cs-1064",module:"changshi",prompt:"根据行政诉讼法，对行政案件有管辖权的第一审法院一般是：",options:["基层人民法院", "中级人民法院", "高级人民法院", "最高人民法院"],answer:0,explanation:"行政诉讼第一审案件原则上由基层人民法院管辖，重大复杂案件由中院以上管辖。"},{id:"cs-1065",module:"changshi",prompt:"根据行政诉讼法，人民法院审理行政案件：",options:["可以调解为原则", "不适用调解（行政赔偿、补偿及行使自由裁量权的案件除外）", "必须调解", "禁止任何调解"],answer:1,explanation:"行政诉讼不适用调解，但行政赔偿、补偿以及行政机关行使法律自由裁量权的案件可以调解。"},{id:"cs-1066",module:"changshi",prompt:"根据行政复议法，对县级以上地方政府具体行政行为不服的，向：",options:["该级政府本身申请复议", "上一级人民政府申请复议", "法院起诉", "国务院申请复议"],answer:1,explanation:"对县级以上地方各级人民政府工作部门或本级政府行为不服的复议管辖，遵循上一级管辖原则。"},{id:"cs-1067",module:"changshi",prompt:"根据行政强制法，行政强制措施的种类不包括：",options:["限制公民人身自由", "查封场所、设施或财物", "扣押财物", "行政拘留"],answer:3,explanation:"行政拘留属于行政处罚，不是行政强制措施；行政强制措施包括限制人身自由、查封、扣押、冻结等。"},{id:"cs-1068",module:"changshi",prompt:"行政机关作出重大执法决定前，应当进行：",options:["法制审核", "群众投票", "媒体公示", "上级批准"],answer:0,explanation:"行政执法三项制度：执法公示、执法全过程记录、重大执法决定法制审核。"},{id:"cs-1069",module:"changshi",prompt:"根据行政处罚法，违法行为在多少年内未被发现的，不再给予行政处罚（法律另有规定除外）？",options:["六个月", "一年", "二年", "五年"],answer:2,explanation:"行政处罚追责时效一般为二年；涉及公民生命健康安全、金融安全且有危害后果的，延长至五年。"},{id:"cs-1070",module:"changshi",prompt:"根据劳动法，劳动者每日工作时间不超过、每周平均工作时间不超过：",options:["8小时、40小时", "8小时、44小时", "7小时、40小时", "9小时、44小时"],answer:1,explanation:"劳动法规定劳动者每日工作时间不超过八小时、平均每周工作时间不超过四十四小时；国务院规定每周工作40小时。"},{id:"cs-1071",module:"changshi",prompt:"根据劳动法，用人单位安排加班，一般每日不得超过：",options:["1小时", "2小时", "3小时", "4小时"],answer:0,explanation:"因生产经营需要延长工作时间，一般每日不得超过一小时；特殊原因每日不超过三小时，每月不超过三十六小时。"},{id:"cs-1072",module:"changshi",prompt:"根据劳动合同法，用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当：",options:["视为已订立无固定期限劳动合同", "每月支付二倍工资", "支付三倍工资", "补签即可不担责"],answer:1,explanation:"超过一个月不满一年未订立书面合同的，应当向劳动者每月支付二倍的工资；满一年的视为已订立无固定期限劳动合同。"},{id:"cs-1073",module:"changshi",prompt:"根据劳动合同法，劳动者在试用期内：",options:["工资不得低于本单位相同岗位最低档工资或合同约定工资的80%", "可以不发工资", "工资由单位随意定", "必须同工同酬"],answer:0,explanation:"试用期工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，且不得低于当地最低工资标准。"},{id:"cs-1074",module:"changshi",prompt:"根据劳动合同法，劳动者提前多少日以书面形式通知用人单位，可以解除劳动合同？",options:["三日", "七日", "十五日", "三十日"],answer:3,explanation:"劳动者提前三十日以书面形式通知用人单位可以解除劳动合同；试用期内提前三日通知即可。"},{id:"cs-1075",module:"changshi",prompt:"根据劳动合同法，竞业限制的人员范围不包括：",options:["高级管理人员", "高级技术人员", "其他负有保密义务的人员", "普通保洁人员"],answer:3,explanation:"竞业限制适用于高级管理人员、高级技术人员和其他负有保密义务的人员，不能扩大到普通员工。"},{id:"cs-1076",module:"changshi",prompt:"根据社会保险法，基本养老保险个人账户的资金：",options:["可以提前支取", "不得提前支取，记账利率不得低于银行定期存款利率", "按活期计息", "归单位所有"],answer:1,explanation:"个人账户不得提前支取，记账利率不得低于银行定期存款利率，个人死亡的，个人账户余额可以继承。"},{id:"cs-1077",module:"changshi",prompt:"根据劳动法，女职工生育享受的产假不少于：",options:["90天", "98天", "128天", "158天"],answer:0,explanation:"劳动法规定女职工生育享受不少于九十天的产假；各地另有生育奖励假，实际天数更长。"},{id:"cs-1078",module:"changshi",prompt:"根据劳动争议调解仲裁法，劳动争议申请仲裁的时效期间为：",options:["六个月", "一年", "二年", "三年"],answer:1,explanation:"劳动争议申请仲裁的时效期间为一年，自当事人知道或者应当知道其权利被侵害之日起计算。"},{id:"cs-1079",module:"changshi",prompt:"根据劳动法，工资应当以何种形式按月支付给劳动者本人？",options:["实物", "货币", "购物券", "股权"],answer:1,explanation:"工资应当以货币形式按月支付给劳动者本人，不得克扣或者无故拖欠。"},{id:"cs-1080",module:"changshi",prompt:"根据公司法，有限责任公司的股东以其：",options:["个人全部财产对公司债务承担责任", "认缴的出资额为限对公司承担责任", "实缴出资额为限", "公司财产为限"],answer:1,explanation:"有限责任公司股东以其认缴的出资额为限对公司承担责任，公司以其全部财产对债务承担责任。"},{id:"cs-1081",module:"changshi",prompt:"根据公司法，股份有限公司的设立方式包括：",options:["只能发起设立", "发起设立和募集设立", "只能募集设立", "审批设立"],answer:1,explanation:"股份有限公司可以采取发起设立或者募集设立的方式。"},{id:"cs-1082",module:"changshi",prompt:"根据消费者权益保护法，经营者提供商品有欺诈行为的，消费者可以要求：",options:["退一赔三，不足五百元的按五百元计", "退一赔一", "退一赔十", "只退货"],answer:0,explanation:"经营者有欺诈行为的，消费者可要求增加赔偿，金额为价款的三倍，不足五百元的为五百元（食品领域退一赔十另有规定）。"},{id:"cs-1083",module:"changshi",prompt:"根据消费者权益保护法，网购商品七日无理由退货的例外不包括：",options:["定制商品", "鲜活易腐商品", "普通服装", "在线下载或拆封的音像制品"],answer:2,explanation:"七日无理由退货不适用于定制商品、鲜活易腐、在线下载或已拆封的音像制品和软件等；普通服装可以无理由退货。"},{id:"cs-1084",module:"changshi",prompt:"根据反不正当竞争法，商业贿赂的对象不包括：",options:["交易相对方的工作人员", "受托人", "利用职权影响交易的单位或个人", "普通消费者"],answer:3,explanation:"商业贿赂指经营者向交易相对方工作人员、受托人、利用职权影响交易的单位或个人输送利益，普通消费者不属于。"},{id:"cs-1085",module:"changshi",prompt:"根据反垄断法，具有竞争关系的经营者达成的横向垄断协议不包括：",options:["固定价格", "限制产量", "划分市场", "纵向价格维持"],answer:3,explanation:"横向垄断协议是竞争者之间的协议；纵向垄断协议是经营者与交易相对人之间的，如固定转售价格。"},{id:"cs-1086",module:"changshi",prompt:"根据票据法，汇票的出票人签发汇票后，即承担：",options:["保证该汇票承兑和付款的责任", "仅付款责任", "仅承兑责任", "无责任"],answer:0,explanation:"出票人签发汇票后，即承担保证该汇票承兑和付款的责任。"},{id:"cs-1087",module:"changshi",prompt:"根据保险法，投保人故意不履行如实告知义务的，保险人：",options:["仍须赔付", "对于合同解除前发生的保险事故不承担赔偿或给付责任", "只赔一半", "延长观察期"],answer:1,explanation:"投保人故意不履行如实告知义务的，保险人不承担赔偿或给付保险金的责任，并不退还保险费。"},{id:"cs-1088",module:"changshi",prompt:"根据个人所得税法，专项附加扣除不包括：",options:["子女教育", "继续教育", "大病医疗", "奢侈品消费"],answer:3,explanation:"专项附加扣除包括子女教育、继续教育、大病医疗、住房贷款利息、住房租金、赡养老人、3岁以下婴幼儿照护等，不含奢侈品消费。"},{id:"cs-1089",module:"changshi",prompt:"根据税收征收管理法，纳税人未按期缴纳税款的，税务机关除责令限期缴纳外，从滞纳税款之日起：",options:["免于追责", "按日加收滞纳税款万分之五的滞纳金", "按日加收千分之五滞纳金", "直接处罚"],answer:1,explanation:"从滞纳税款之日起，按日加收滞纳税款万分之五的滞纳金。"},{id:"cs-1090",module:"changshi",prompt:"根据民事诉讼法，一般地域管辖的原则是：",options:["原告就被告", "被告就原告", "就近管辖", "随机指定"],answer:0,explanation:"民事诉讼一般由被告住所地人民法院管辖，即原告就被告原则。"},{id:"cs-1091",module:"changshi",prompt:"根据民事诉讼法，适用普通程序审理的一审民事案件，审限为：",options:["三个月", "六个月", "九个月", "一年"],answer:1,explanation:"适用普通程序审理的一审民事案件，应当在立案之日起六个月内审结；简易程序为三个月。"},{id:"cs-1092",module:"changshi",prompt:"根据刑事诉讼法，逮捕犯罪嫌疑人、被告人，必须经过：",options:["公安机关决定", "人民检察院批准或者人民法院决定", "司法局批准", "政法委批准"],answer:1,explanation:"逮捕必须经人民检察院批准或者人民法院决定，由公安机关执行。"},{id:"cs-1093",module:"changshi",prompt:"根据刑事诉讼法，犯罪嫌疑人自被侦查机关第一次讯问或者采取强制措施之日起，有权：",options:["委托辩护人", "直接取保候审", "拒绝讯问", "要求公开审理"],answer:0,explanation:"犯罪嫌疑人自被侦查机关第一次讯问或者采取强制措施之日起，有权委托辩护人；在侦查期间只能委托律师作为辩护人。"},{id:"cs-1094",module:"changshi",prompt:"根据行政诉讼法，被告对作出的行政行为负有：",options:["举证责任", "调解义务", "反诉权利", "选择管辖权"],answer:0,explanation:"行政诉讼中被告（行政机关）对作出的行政行为负有举证责任，应当提供作出该行为的证据和所依据的规范性文件。"},{id:"cs-1095",module:"changshi",prompt:"根据民事诉讼法，当事人对一审判决不服的上诉期为：",options:["十日", "十五日", "二十日", "三十日"],answer:1,explanation:"对一审判决不服的上诉期为十五日，对裁定不服的上诉期为十日，自判决书送达之日起计算。"},{id:"cs-1096",module:"changshi",prompt:"根据刑事诉讼法，刑事案件的追诉时效，法定最高刑为无期徒刑、死刑的，经过：",options:["十年", "十五年", "二十年", "不受限制"],answer:2,explanation:"法定最高刑为无期徒刑、死刑的，经过二十年不再追诉；如认为必须追诉的，须报最高人民检察院核准。"},{id:"cs-1097",module:"changshi",prompt:"根据民事诉讼法，证据的种类不包括：",options:["书证", "物证", "当事人陈述", "新闻舆论"],answer:3,explanation:"民事证据包括书证、物证、视听资料、电子数据、证人证言、当事人陈述、鉴定意见、勘验笔录，新闻舆论不是法定证据种类。"},{id:"cs-1098",module:"changshi",prompt:"我国法律渊源中效力层级最高的是：",options:["宪法", "法律", "行政法规", "地方性法规"],answer:0,explanation:"宪法具有最高法律效力，一切法律、行政法规、地方性法规都不得同宪法相抵触。"},{id:"cs-1099",module:"changshi",prompt:"法律效力层级从高到低排列正确的是：",options:["宪法—法律—行政法规—地方性法规", "宪法—行政法规—法律—地方性法规", "法律—宪法—行政法规—地方性法规", "宪法—地方性法规—法律—行政法规"],answer:0,explanation:"我国法律效力层级：宪法＞法律＞行政法规＞地方性法规＞规章。"},{id:"cs-1100",module:"changshi",prompt:"法的规范作用不包括：",options:["指引作用", "评价作用", "预测作用", "决定经济发展方向"],answer:3,explanation:"法的规范作用包括指引、评价、预测、教育和强制作用；法不能直接决定经济发展方向。"},{id:"cs-1101",module:"changshi",prompt:"我国立法体制的特点是：",options:["一元、两级、多层次", "联邦制", "判例法", "单一法典"],answer:0,explanation:"我国立法体制是统一而又分层次的一元两级立法体制，全国人大及其常委会行使国家立法权。"},{id:"cs-1102",module:"changshi",prompt:"法律关系的内容是：",options:["法律主体", "权利和义务", "法律事实", "法律客体"],answer:1,explanation:"法律关系由主体、内容和客体构成，内容是法律关系主体之间的权利和义务。"},{id:"cs-1103",module:"changshi",prompt:"能够引起法律关系产生、变更、消灭的是：",options:["法律事实", "法律条文", "法律意识", "法律部门"],answer:0,explanation:"法律事实是法律关系产生、变更和消灭的原因，分为法律事件和法律行为。"},{id:"cs-1104",module:"changshi",prompt:"我国刑法的基本原则不包括：",options:["罪刑法定原则", "法律面前人人平等原则", "罪责刑相适应原则", "疑罪从无原则"],answer:3,explanation:"刑法三大基本原则：罪刑法定、法律面前人人平等、罪责刑相适应；疑罪从无是刑事诉讼法原则，不是刑法基本原则。"},{id:"cs-1105",module:"changshi",prompt:"我国民法典的立法目的是：",options:["保护民事主体的合法权益，调整民事关系", "规范行政行为", "规定犯罪与刑罚", "规范外交关系"],answer:0,explanation:"民法典第一条：保护民事主体的合法权益，调整民事关系，维护社会经济秩序。"},{id:"cs-1106",module:"changshi",prompt:"我国法律对人的效力，采取的主义是：",options:["属地主义为主，属人主义、保护主义相结合", "纯属地主义", "纯属人主义", "纯保护主义"],answer:0,explanation:"我国法律对人的效力采取以属地主义为主，与属人主义、保护主义相结合的原则。"},{id:"cs-1107",module:"changshi",prompt:"我国宪法规定，国家主席、副主席由谁选举产生？",options:["全国人民代表大会", "全国人大常委会", "国务院", "中共中央"],answer:0,explanation:"国家主席、副主席由全国人民代表大会选举产生，有选举权和被选举权的年满四十五周岁的中国公民可以被选为正副主席。"},{id:"cs-1108",module:"changshi",prompt:"我国宪法规定，有权解释宪法和法律的是：",options:["全国人民代表大会", "全国人大常委会", "最高人民法院", "国务院"],answer:1,explanation:"全国人大常委会行使解释宪法、监督宪法实施的职权，并解释法律。"},{id:"cs-1109",module:"changshi",prompt:"我国宪法规定，中央军事委员会主席对谁负责？",options:["全国人民代表大会", "全国人大常委会", "中共中央", "国家主席"],answer:0,explanation:"中央军事委员会主席对全国人民代表大会负责；在全国人大闭会期间，对全国人大常委会负责。"},{id:"cs-1110",module:"changshi",prompt:"我国宪法规定，审计机关在谁领导下依法独立行使审计监督权？",options:["国务院总理", "审计长", "本级政府", "监察委员会"],answer:0,explanation:"国务院设立审计机关，在国务院总理领导下依法独立行使审计监督权，不受其他行政机关、团体和个人的干涉。"},{id:"cs-1111",module:"changshi",prompt:"我国宪法规定，中华人民共和国的武装力量属于：",options:["中国共产党", "人民", "国家主席", "中央军委"],answer:1,explanation:"宪法规定中华人民共和国的武装力量属于人民，任务是巩固国防、抵抗侵略、保卫祖国。"},{id:"cs-1112",module:"changshi",prompt:"我国宪法规定，公民的哪项义务既是权利又是义务？",options:["纳税", "劳动和受教育", "服兵役", "计划生育"],answer:1,explanation:"宪法规定劳动和受教育既是公民的基本权利，也是公民的基本义务。"},{id:"cs-1113",module:"changshi",prompt:"我国宪法规定，行使国家立法权的机关是：",options:["全国人大及其常委会", "国务院", "最高人民法院", "中央军委"],answer:0,explanation:"全国人民代表大会和全国人民代表大会常务委员会行使国家立法权。"},{id:"cs-1114",module:"changshi",prompt:"我国宪法规定，任何组织或者个人都不得有超越：",options:["道德的特权", "宪法和法律的特权", "政策的特权", "纪律的特权"],answer:1,explanation:"宪法规定任何组织或者个人都不得有超越宪法和法律的特权，体现法律面前人人平等。"},{id:"cs-1115",module:"changshi",prompt:"我国宪法规定，国家厉行节约，反对浪费，合理利用资源，这属于：",options:["公民义务", "国家基本政策", "司法原则", "国际义务"],answer:1,explanation:"宪法规定国家厉行节约、反对浪费，合理利用资源，属于国家的基本政策和制度安排。"},{id:"cs-1116",module:"changshi",prompt:"我国宪法规定，土地的使用权可以依照法律的规定：",options:["无偿转让", "转让", "永久占有", "强制征收"],answer:1,explanation:"宪法规定土地的使用权可以依照法律的规定转让，但所有权归属不变。"},{id:"cs-1117",module:"changshi",prompt:"根据民法典，自然人的民事行为能力分为：",options:["两级", "三级", "四级", "五级"],answer:1,explanation:"自然人的民事行为能力分为完全民事行为能力、限制民事行为能力和无民事行为能力三级。"},{id:"cs-1118",module:"changshi",prompt:"根据民法典，十六周岁以上的未成年人以自己的劳动收入为主要生活来源的：",options:["仍属限制民事行为能力人", "视为完全民事行为能力人", "属于无民事行为能力人", "需法院认定"],answer:1,explanation:"十六周岁以上不满十八周岁的未成年人，以自己的劳动收入为主要生活来源的，视为完全民事行为能力人。"},{id:"cs-1119",module:"changshi",prompt:"根据民法典，宣告失踪的条件是自然人下落不明满：",options:["一年", "二年", "三年", "四年"],answer:1,explanation:"自然人下落不明满二年的，利害关系人可以向人民法院申请宣告失踪。"},{id:"cs-1120",module:"changshi",prompt:"根据民法典，一般保证的保证人在主合同纠纷未经审判或仲裁并就债务人财产依法强制执行仍不能履行前：",options:["应当直接承担保证责任", "有权拒绝向债权人承担保证责任", "与债务人承担连带责任", "自动免责"],answer:1,explanation:"一般保证的保证人享有先诉抗辩权，在就债务人财产依法强制执行仍不能履行债务前，有权拒绝承担保证责任。"},{id:"cs-1121",module:"changshi",prompt:"根据民法典，无民事行为能力人或者限制民事行为能力人的监护人，履行监护职责的原则是：",options:["按监护人的意愿", "最有利于被监护人的原则", "按家庭财产分配", "按长辈意见"],answer:1,explanation:"监护人应当按照最有利于被监护人的原则履行监护职责，不得侵害被监护人的合法权益。"},{id:"cs-1122",module:"changshi",prompt:"根据民法典，因保护他人民事权益使自己受到损害的，由谁承担民事责任？",options:["自己承担", "侵权人承担，受益人可以给予适当补偿", "受益人全部承担", "国家承担"],answer:1,explanation:"因保护他人民事权益使自己受到损害的，由侵权人承担民事责任，受益人可以给予适当补偿。"},{id:"cs-1123",module:"changshi",prompt:"根据民法典，合同成立后，合同的基础条件发生重大变化，继续履行对一方明显不公平的，当事人可以：",options:["直接解除合同", "请求重新协商，协商不成的可以请求法院或仲裁机构变更或解除", "拒绝履行", "要求对方赔偿"],answer:1,explanation:"这是情势变更制度：合同成立后基础条件发生重大变化，可请求重新协商；协商不成的，可请求法院或仲裁机构变更或解除合同。"},{id:"cs-1124",module:"changshi",prompt:"根据民法典，承担民事责任的方式不包括：",options:["停止侵害", "返还财产", "支付违约金", "行政拘留"],answer:3,explanation:"行政拘留是行政处罚，不是民事责任承担方式；民事责任方式包括停止侵害、排除妨碍、返还财产、赔偿损失、支付违约金等。"},{id:"cs-1125",module:"changshi",prompt:"根据民法典，当事人一方不履行合同义务给对方造成损失的，赔偿额应当：",options:["不超过实际损失", "相当于因违约所造成的损失，包括合同履行后可以获得的利益", "由违约方自定", "只赔直接损失"],answer:1,explanation:"损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益，但不得超过违约方订立合同时预见或应当预见的损失。"},{id:"cs-1126",module:"changshi",prompt:"根据民法典，收养人应当年满：",options:["25周岁", "30周岁", "35周岁", "40周岁"],answer:1,explanation:"收养人应当同时具备无子女或只有一名子女、年满三十周岁、有抚养能力等条件。"},{id:"cs-1127",module:"changshi",prompt:"根据民法典，因自愿参加具有一定风险的文体活动受到损害的，其他参加者对损害的发生有故意或重大过失的：",options:["组织者一律赔偿", "其他参加者才承担责任，自甘风险原则下不得请求没有过错的参加者赔偿", "全部参加者分担", "国家赔偿"],answer:1,explanation:"这是自甘风险规则：自愿参加具有一定风险的文体活动，因其他参加者的行为受到损害的，不得请求没有故意或重大过失的其他参加者承担侵权责任。"},{id:"cs-1128",module:"changshi",prompt:"根据民法典，遗产管理人未尽职守造成继承人损失的：",options:["不承担责任", "应当承担民事责任", "只赔一半", "由法院酌定"],answer:1,explanation:"遗产管理人未尽职责造成继承人、受遗赠人损害的，应当承担民事责任。"},{id:"cs-1129",module:"changshi",prompt:"根据民法典，人格权不得放弃、转让或者继承，但：",options:["可以抵押", "姓名、名称、肖像等可以许可他人使用", "可以买卖", "可以出租"],answer:1,explanation:"人格权不得放弃、转让或继承，但民事主体可以将自己的姓名、名称、肖像等许可他人使用。"},{id:"cs-1130",module:"changshi",prompt:"根据民法典，一方以欺诈手段使对方在违背真实意思的情况下实施的民事法律行为，对方有权：",options:["直接撕毁合同", "请求人民法院或仲裁机构予以撤销", "要求加倍赔偿", "自动无效"],answer:1,explanation:"一方以欺诈手段使对方在违背真实意思的情况下实施的民事法律行为，受欺诈方有权请求法院或仲裁机构予以撤销。"},{id:"cs-1131",module:"changshi",prompt:"根据民法典，抵押期间抵押人转让抵押财产的：",options:["一律无效", "当事人另有约定的除外，抵押财产转让的应通知抵押权人", "必须先解除抵押", "由法院批准"],answer:1,explanation:"抵押期间抵押人可以转让抵押财产，但当事人另有约定的除外；转让的应当及时通知抵押权人。"},{id:"cs-1132",module:"changshi",prompt:"根据刑法，故意犯罪与过失犯罪区分的核心是：",options:["行为方式", "对危害结果的心理态度", "犯罪动机", "危害后果大小"],answer:1,explanation:"故意是明知自己的行为会发生危害结果并希望或放任；过失是应当预见因疏忽大意没有预见或已经预见但轻信能够避免。"},{id:"cs-1133",module:"changshi",prompt:"根据刑法，紧急避险与正当防卫的本质区别在于：",options:["针对的对象不同：紧急避险损害的是第三者的合法权益", "危害程度不同", "主观意图不同", "法律后果不同"],answer:0,explanation:"正当防卫针对不法侵害人本人，紧急避险是损害第三者合法权益以保全更大利益。"},{id:"cs-1134",module:"changshi",prompt:"根据刑法，剥夺政治权利的刑罚，属于：",options:["主刑", "附加刑", "行政处分", "民事责任"],answer:1,explanation:"剥夺政治权利是附加刑，可以独立适用，也可以附加于主刑适用。"},{id:"cs-1135",module:"changshi",prompt:"根据刑法，被判处管制的犯罪分子，在执行期间：",options:["必须入监服刑", "依法实行社区矫正", "由公安机关关押", "由家属看管"],answer:1,explanation:"被判处管制的犯罪分子依法实行社区矫正，不关押，但须遵守相关规定。"},{id:"cs-1136",module:"changshi",prompt:"根据刑法，死刑缓期执行期间，如果没有故意犯罪：",options:["立即执行死刑", "二年期满后减为无期徒刑", "减为有期徒刑", "赦免"],answer:1,explanation:"判处死刑缓期执行的，在死刑缓期执行期间如没有故意犯罪，二年期满后减为无期徒刑。"},{id:"cs-1137",module:"changshi",prompt:"根据刑法，追诉时效的期限，法定最高刑为五年以上不满十年有期徒刑的，经过：",options:["五年", "十年", "十五年", "二十年"],answer:1,explanation:"法定最高刑为五年以上不满十年有期徒刑的，经过十年不再追诉。"},{id:"cs-1138",module:"changshi",prompt:"根据刑法，单位犯罪的，对单位判处罚金，并对其：",options:["全体员工判刑", "直接负责的主管人员和其他直接责任人员判处刑罚", "法定代表人个人判刑", "股东判刑"],answer:1,explanation:"单位犯罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员判处刑罚。"},{id:"cs-1139",module:"changshi",prompt:"根据刑法，犯罪集团的首要分子，按照：",options:["个人所得数额处罚", "集团所犯的全部罪行处罚", "从轻处罚", "免予处罚"],answer:1,explanation:"对组织、领导犯罪集团的首要分子，按照集团所犯的全部罪行处罚。"},{id:"cs-1140",module:"changshi",prompt:"根据刑法，教唆不满十八周岁的人犯罪的：",options:["从轻处罚", "应当从重处罚", "免予处罚", "与被教唆者同等处罚"],answer:1,explanation:"教唆他人犯罪的，应当按照他在共同犯罪中所起的作用处罚；教唆不满十八周岁的人犯罪的，应当从重处罚。"},{id:"cs-1141",module:"changshi",prompt:"根据刑法，罚金刑的执行：",options:["可分期缴纳，确有困难可减免", "必须一次缴清", "可用人身抵偿", "由家属代缴"],answer:0,explanation:"罚金可以分期缴纳，由于不能抗拒的灾祸等原因缴纳确有困难的，可以裁定减少或者免除。"},{id:"cs-1142",module:"changshi",prompt:"根据行政处罚法，行政处罚的种类不包括：",options:["警告、通报批评", "罚款、没收违法所得", "行政拘留", "开除公职"],answer:3,explanation:"开除公职属于行政处分（对公务员的内部惩戒），不是行政处罚。"},{id:"cs-1143",module:"changshi",prompt:"根据行政许可法，法律、行政法规设定的行政许可，其适用范围：",options:["仅限本行政区域", "没有地域限制", "由发证机关指定", "仅限城市"],answer:1,explanation:"法律、行政法规设定的行政许可，其适用范围没有地域限制的，申请人取得的行政许可在全国范围内有效。"},{id:"cs-1144",module:"changshi",prompt:"根据行政强制法，查封、扣押的期限不得超过：",options:["十日", "十五日", "三十日", "六十日"],answer:2,explanation:"查封、扣押的期限不得超过三十日；情况复杂的，经批准可以延长，但延长期限不得超过三十日。"},{id:"cs-1145",module:"changshi",prompt:"根据国家赔偿法，侵犯公民人身自由的，每日赔偿金按照：",options:["当地最低工资", "国家上年度职工日平均工资计算", "受害人实际收入", "全国平均工资"],answer:1,explanation:"侵犯公民人身自由的，每日赔偿金按照国家上年度职工日平均工资计算。"},{id:"cs-1146",module:"changshi",prompt:"根据行政诉讼法，行政诉讼的被告是：",options:["作出行政行为的行政机关", "行政机关工作人员", "行政行为的相对人", "检察院"],answer:0,explanation:"行政诉讼的被告是作出行政行为的行政机关；行政机关工作人员不直接作为被告。"},{id:"cs-1147",module:"changshi",prompt:"根据行政复议法，行政复议决定一般应当在受理申请之日起多少日内作出？",options:["三十日", "六十日", "九十日", "一百二十日"],answer:1,explanation:"行政复议机关应当自受理申请之日起六十日内作出行政复议决定，法律规定少于六十日的除外。"},{id:"cs-1148",module:"changshi",prompt:"根据行政法基本理论，行政行为合法的要件不包括：",options:["主体合法", "权限合法", "内容合法适当", "相对人同意"],answer:3,explanation:"行政行为合法要件包括主体合法、权限合法、内容合法适当、程序合法，不以相对人同意为要件。"},{id:"cs-1149",module:"changshi",prompt:"根据行政处罚法，当事人要求听证的，应当在行政机关告知后：",options:["三日内", "五日内", "十日内", "十五日内"],answer:1,explanation:"行政机关拟作出较大数额罚款等决定前应告知听证权，当事人要求听证的应当在告知后五日内提出。"},{id:"cs-1150",module:"changshi",prompt:"根据公务员法，公务员的录用方式主要是：",options:["委任制", "公开考试、严格考察、平等竞争、择优录取", "聘任制", "选举制"],answer:1,explanation:"录用担任一级主任科员以下及其他相当职级层次的公务员，采取公开考试、严格考察、平等竞争、择优录取的办法。"},{id:"cs-1151",module:"changshi",prompt:"根据行政法，行政法的基本原则不包括：",options:["合法行政原则", "合理行政原则", "高效便民原则", "意思自治原则"],answer:3,explanation:"意思自治是民法原则；行政法基本原则包括合法行政、合理行政、程序正当、高效便民、诚实守信、权责统一。"},{id:"cs-1152",module:"changshi",prompt:"根据劳动合同法，劳动合同期限三个月以上不满一年的，试用期不得超过：",options:["一个月", "二个月", "三个月", "六个月"],answer:0,explanation:"劳动合同期限三个月以上不满一年的，试用期不得超过一个月；一年以上不满三年的，不超过二个月；三年以上或无固定期限的，不超过六个月。"},{id:"cs-1153",module:"changshi",prompt:"根据劳动合同法，用人单位可以随时解除劳动合同且不支付经济补偿的情形是：",options:["劳动者不能胜任工作", "劳动者严重违反规章制度", "企业经济性裁员", "客观情况重大变化"],answer:1,explanation:"劳动者严重违反规章制度或被追究刑事责任的，用人单位可以解除合同且无需支付经济补偿。"},{id:"cs-1154",module:"changshi",prompt:"根据劳动合同法，经济补偿按劳动者在本单位工作的年限，每满一年支付：",options:["半个月工资", "一个月工资", "二个月工资", "三个月工资"],answer:1,explanation:"经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付，六个月以上不满一年的按一年计算。"},{id:"cs-1155",module:"changshi",prompt:"根据劳动法，国家对女职工和未成年工实行：",options:["同工同酬即可", "特殊劳动保护", "不安排工作", "降低工资"],answer:1,explanation:"国家对女职工和未成年工实行特殊劳动保护，如禁止安排从事矿山井下等禁忌劳动。"},{id:"cs-1156",module:"changshi",prompt:"根据劳动法，未成年工是指年满多少周岁的劳动者？",options:["14周岁未满16周岁", "16周岁未满18周岁", "18周岁未满20周岁", "14周岁未满18周岁"],answer:1,explanation:"未成年工是指年满十六周岁未满十八周岁的劳动者，国家对其实行特殊劳动保护。"},{id:"cs-1157",module:"changshi",prompt:"根据社会保险法，失业保险金的领取期限最长不超过：",options:["十二个月", "十八个月", "二十四个月", "三十六个月"],answer:2,explanation:"失业保险金领取期限最长不超过二十四个月，具体根据缴费年限确定。"},{id:"cs-1158",module:"changshi",prompt:"根据劳动合同法，无固定期限劳动合同的订立情形不包括：",options:["连续工作满十年", "连续订立二次固定期限劳动合同且续订", "初次入职", "用人单位初次实行劳动合同制度时连续工作满十年"],answer:2,explanation:"初次入职不产生无固定期限劳动合同的订立义务；连续工作满十年、连续订立二次固定期限合同后续订等情形才涉及。"},{id:"cs-1159",module:"changshi",prompt:"根据劳动法，用人单位拖欠或者未足额支付劳动报酬的，劳动者可以：",options:["直接离职并要求经济补偿", "向当地人民法院申请支付令", "只能仲裁", "只能起诉"],answer:1,explanation:"用人单位拖欠或者未足额支付劳动报酬的，劳动者可以依法向当地人民法院申请支付令，人民法院应当依法发出支付令。"},{id:"cs-1160",module:"changshi",prompt:"根据公司法，公司营业执照签发日期为：",options:["公司章程制定日", "公司成立日期", "股东会召开日", "验资完成日"],answer:1,explanation:"公司营业执照签发日期为公司成立日期。"},{id:"cs-1161",module:"changshi",prompt:"根据公司法，一人有限责任公司的股东不能证明公司财产独立于股东自己的财产的：",options:["公司有效", "应当对公司债务承担连带责任", "公司自动解散", "股东免责"],answer:1,explanation:"一人有限责任公司股东不能证明公司财产独立于股东自己的财产的，应当对公司债务承担连带责任（法人人格否认）。"},{id:"cs-1162",module:"changshi",prompt:"根据消费者权益保护法，经营者不得以格式条款等方式作出排除或者限制消费者权利的规定，其效力是：",options:["有效", "无效", "可撤销", "效力待定"],answer:1,explanation:"经营者以格式条款、通知、声明、店堂告示等方式作出排除或者限制消费者权利、减轻或免除经营者责任的规定，其内容无效。"},{id:"cs-1163",module:"changshi",prompt:"根据消费者权益保护法，消费者在购买商品时权益受损，可以向谁要求赔偿？",options:["只能向销售者", "销售者或生产者（视情形可向任一方）", "只能向生产者", "只能向电商平台"],answer:1,explanation:"消费者可以向销售者要求赔偿，也可以向生产者要求赔偿，属于生产者责任的由销售者赔偿后向生产者追偿。"},{id:"cs-1164",module:"changshi",prompt:"根据反不正当竞争法，经营者不得实施混淆行为，引人误认是他人商品或者与他人存在特定联系，这保护的是：",options:["消费者知情权", "商业标识（含有一定影响的商品名称、企业名称、域名等）", "商标专用权", "专利权"],answer:1,explanation:"混淆行为条款保护的是有一定影响的商业标识，包括商品名称、包装装潢、企业名称、域名等。"},{id:"cs-1165",module:"changshi",prompt:"根据反垄断法，经营者集中达到申报标准的：",options:["可以自由实施", "应当事先向国务院反垄断执法机构申报，未申报的不得实施", "禁止一切并购", "由行业协会批准"],answer:1,explanation:"达到国务院规定的申报标准的经营者集中，应当事先申报，未申报的不得实施集中。"},{id:"cs-1166",module:"changshi",prompt:"根据保险法，保险合同的犹豫期（撤单期）内投保人解除合同的，保险人应当：",options:["扣除手续费后退保", "退还已收取的全部保险费", "不退保费", "赔偿损失"],answer:1,explanation:"投保人在犹豫期内解除合同的，保险人应当退还已收取的全部保险费（另有约定除外）。"},{id:"cs-1167",module:"changshi",prompt:"根据票据法，票据金额以中文大写和数码同时记载，二者不一致的：",options:["以中文大写为准", "以数码为准", "票据无效", "由法院认定"],answer:2,explanation:"票据金额以中文大写和数码同时记载，二者不一致的，票据无效。"},{id:"cs-1168",module:"changshi",prompt:"根据个人所得税法，居民个人是指在中国境内有住所，或者无住所而一个纳税年度内在中国境内居住累计满：",options:["90天", "183天", "365天", "30天"],answer:1,explanation:"在中国境内有住所，或者无住所而一个纳税年度内在中国境内居住累计满一百八十三天的个人，为居民个人。"},{id:"cs-1169",module:"changshi",prompt:"根据电子商务法，电子商务平台经营者知道平台内经营者销售商品不符合保障人身安全要求，未采取必要措施的：",options:["不承担责任", "与该平台内经营者承担连带责任", "仅承担补充责任", "由监管部门处理"],answer:1,explanation:"电子商务平台经营者知道或者应当知道平台内经营者销售的商品不符合保障人身、财产安全要求，未采取必要措施的，依法与该平台内经营者承担连带责任。"},{id:"cs-1170",module:"changshi",prompt:"根据民事诉讼法，简易程序审理的民事案件，审限为：",options:["一个月", "三个月", "六个月", "一年"],answer:1,explanation:"适用简易程序审理的民事案件应当在立案之日起三个月内审结，不得延长。"},{id:"cs-1171",module:"changshi",prompt:"根据民事诉讼法，下列人员中不能作为证人的是：",options:["未成年人", "不能正确表达意思的人", "聋哑人", "文盲"],answer:1,explanation:"凡是知道案件情况的单位和个人都有义务出庭作证；不能正确表达意思的人不能作为证人。"},{id:"cs-1172",module:"changshi",prompt:"根据刑事诉讼法，取保候审的最长期限为：",options:["一个月", "三个月", "六个月", "十二个月"],answer:3,explanation:"取保候审最长不得超过十二个月，监视居住最长不得超过六个月。"},{id:"cs-1173",module:"changshi",prompt:"根据刑事诉讼法，第二审人民法院审理上诉案件，不得：",options:["书面审理", "开庭审理", "加重被告人刑罚（上诉不加刑原则，检察院抗诉除外）", "发回重审"],answer:2,explanation:"第二审人民法院审理被告人一方上诉的案件，不得加重被告人的刑罚，即上诉不加刑原则；检察院抗诉或自诉人上诉的除外。"},{id:"cs-1174",module:"changshi",prompt:"根据行政诉讼法，人民法院审理行政案件，参照适用：",options:["宪法", "法律和行政法规", "规章（合法有效的）", "党内法规"],answer:2,explanation:"人民法院审理行政案件，以法律和行政法规、地方性法规为依据，参照规章。"},{id:"cs-1175",module:"changshi",prompt:"根据民事诉讼法，申请执行的期间为：",options:["六个月", "一年", "二年", "五年"],answer:2,explanation:"申请执行的期间为二年，自法律文书规定履行期间的最后一日起计算。"},{id:"cs-1176",module:"changshi",prompt:"根据刑事诉讼法，下列强制措施中剥夺人身自由最严厉的是：",options:["拘传", "取保候审", "监视居住", "逮捕"],answer:3,explanation:"逮捕是刑事诉讼中最严厉的强制措施，完全剥夺人身自由。"},{id:"cs-1177",module:"changshi",prompt:"根据民事诉讼法，公告送达的公告期届满日为：",options:["三十日", "六十日", "九十日", "一百二十日"],answer:1,explanation:"公告送达自发出公告之日起，经过六十日即视为送达（涉外案件为三个月）。"},{id:"cs-1178",module:"changshi",prompt:"我国现行法律体系中，部门法划分的主要标准是：",options:["法律调整的对象和方法", "法律制定时间", "法律制定机关", "法律条文数量"],answer:0,explanation:"划分部门法的主要标准是法律所调整的社会关系（对象），辅之以调整方法。"},{id:"cs-1179",module:"changshi",prompt:"法律汇编与法律编纂的区别在于：",options:["法律编纂是立法活动，可改变法律内容", "法律汇编改变内容", "二者相同", "法律汇编效力更高"],answer:0,explanation:"法律汇编是对现行法律规范性文件汇总整理，不改变内容；法律编纂是立法活动，可以修改、补充法律内容。"},{id:"cs-1180",module:"changshi",prompt:"我国法律监督体系中，宪法监督的机关是：",options:["全国人大及其常委会", "最高人民法院", "监察委员会", "检察院"],answer:0,explanation:"全国人大及其常委会负责监督宪法实施，是我国的宪法监督机关。"},{id:"cs-1181",module:"changshi",prompt:"法的溯及力的一般原则是：",options:["法不溯及既往，但新法对保护权益更有利的除外", "一律溯及既往", "一律不溯及既往", "由法官裁量"],answer:0,explanation:"我国采取法不溯及既往为原则，但新法不认为是违法或处罚更轻的适用新法（从旧兼从轻）。"},{id:"cs-1182",module:"changshi",prompt:"法律解释中，正式解释（有权解释）的主体不包括：",options:["全国人大常委会", "最高人民法院", "最高人民检察院", "法学教授"],answer:3,explanation:"正式解释由法定机关作出，如全国人大常委会（立法解释）、最高法、最高检（司法解释）；学理解释不是正式解释。"},{id:"cs-1183",module:"changshi",prompt:"法律关系客体的种类不包括：",options:["物", "人身利益", "行为", "思想观念本身"],answer:3,explanation:"法律关系客体包括物、人身利益、行为（行为结果）、智力成果等；思想观念本身未经外化不能成为客体。"},{id:"cs-1184",module:"changshi",prompt:"我国宪法宣誓制度体现了：",options:["宪法至上", "司法独立", "立法民主", "行政效率"],answer:0,explanation:"宪法宣誓制度体现宪法作为根本法的最高地位，增强国家工作人员的宪法意识。"},{id:"cs-1185",module:"changshi",prompt:"根据立法法，法律的效力高于：",options:["宪法", "行政法规、地方性法规、规章", "国际条约", "判例"],answer:1,explanation:"法律的效力高于行政法规、地方性法规、规章；行政法规的效力高于地方性法规、规章。"},{id:"cs-1186",module:"changshi",prompt:"根据立法法，同一机关制定的法律，新的规定与旧的规定不一致的：",options:["适用旧的规定", "适用新的规定", "由法院选择", "同时适用"],answer:1,explanation:"同一机关制定的法律，新的规定与旧的规定不一致的，适用新的规定（新法优于旧法）。"},{id:"cs-1187",module:"changshi",prompt:"根据立法法，部门规章之间、部门规章与地方政府规章之间具有：",options:["同等效力，在各自权限范围内施行", "部门规章效力更高", "地方政府规章效力更高", "由国务院裁定效力"],answer:0,explanation:"部门规章之间、部门规章与地方政府规章之间具有同等效力，在各自的权限范围内施行。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-1188",module:"changshi",prompt:"商朝刻在龟甲兽骨上的文字称为：",options:["金文", "甲骨文", "小篆", "隶书"],answer:1,explanation:"甲骨文是商朝刻写在龟甲兽骨上的文字，是我国目前已知最早的成熟文字体系。"},{id:"cs-1189",module:"changshi",prompt:"西周实行的分封制中，受封的主体主要是：",options:["平民", "王族、功臣和先代贵族后裔", "商人", "军人"],answer:1,explanation:"西周分封制分封对象主要是王族（同姓亲族）、功臣和先代贵族后裔，形成层层分封的等级结构。"},{id:"cs-1190",module:"changshi",prompt:"春秋战国时期，铁器和牛耕的使用带来的直接影响是：",options:["人口减少", "农业生产效率提高", "战争减少", "文字统一"],answer:1,explanation:"铁农具和牛耕推广提高了农业生产效率，大量荒地被开垦，推动井田制瓦解。"},{id:"cs-1191",module:"changshi",prompt:"秦朝统一后推行的标准文字是：",options:["甲骨文", "金文", "小篆", "楷书"],answer:2,explanation:"秦朝统一文字，以小篆为标准字体，后隶书在日常使用中逐渐流行。"},{id:"cs-1192",module:"changshi",prompt:"秦朝为加强统治在地方推行的制度是：",options:["分封制", "郡县制", "行省制", "州郡制"],answer:1,explanation:"秦朝废除分封制，在全国推行郡县制，地方长官由中央任命，是中央集权制度的重要基础。"},{id:"cs-1193",module:"changshi",prompt:"汉武帝时期为加强思想控制采纳的建议是：",options:["焚书坑儒", "罢黜百家，独尊儒术", "以佛治心", "重法轻儒"],answer:1,explanation:"汉武帝采纳董仲舒建议，罢黜百家、独尊儒术，儒学成为封建社会正统思想。"},{id:"cs-1194",module:"changshi",prompt:"丝绸之路开通于哪个朝代？",options:["秦朝", "西汉", "东汉", "唐朝"],answer:1,explanation:"西汉张骞两次出使西域后，丝绸之路正式开通，连接中原与中亚、西亚直至欧洲。"},{id:"cs-1195",module:"changshi",prompt:"三国时期，蜀汉的建立者是：",options:["刘备", "曹操", "孙权", "诸葛亮"],answer:0,explanation:"221年刘备在成都称帝，国号汉，史称蜀汉。"},{id:"cs-1196",module:"changshi",prompt:"西晋灭亡后，司马睿在南方建立的政权是：",options:["东吴", "东晋", "南朝宋", "后梁"],answer:1,explanation:"317年司马睿在建康重建晋朝，史称东晋，北方进入十六国时期。"},{id:"cs-1197",module:"changshi",prompt:"北魏孝文帝改革的核心内容是：",options:["均田制与汉化政策", "分封诸子", "重农抑商", "科举取士"],answer:0,explanation:"北魏孝文帝推行均田制，迁都洛阳，改汉姓、说汉语、通婚姻，加速了民族融合。"},{id:"cs-1198",module:"changshi",prompt:"科举制度正式确立于哪个朝代？",options:["隋朝", "唐朝", "宋朝", "明朝"],answer:1,explanation:"隋炀帝始设进士科，唐朝继承并完善，科举制度正式确立。"},{id:"cs-1199",module:"changshi",prompt:"唐朝由盛转衰的转折事件是：",options:["玄武门之变", "安史之乱", "黄巢起义", "陈桥兵变"],answer:1,explanation:"安史之乱（755—763年）使唐朝由盛转衰，此后形成藩镇割据局面。"},{id:"cs-1200",module:"changshi",prompt:"宋朝为加强皇权在中央实行的制度是：",options:["三司会审", "二府三司制，分割宰相权力", "内阁制", "军机处"],answer:1,explanation:"宋朝设中书门下（政事堂）、枢密院、三司，分别掌行政、军事、财政，分割宰相权力。"},{id:"cs-1201",module:"changshi",prompt:"元朝地方行政制度的最大特点是：",options:["推行行省制度", "恢复分封制", "实行郡国并行", "推行州县二级制"],answer:0,explanation:"元朝在地方推行行省制度，是我国省制的开端，加强了中央对辽阔疆域的管理。"},{id:"cs-1202",module:"changshi",prompt:"明朝废除丞相制度的皇帝是：",options:["明太祖朱元璋", "明成祖朱棣", "明仁宗", "明宣宗"],answer:0,explanation:"明太祖朱元璋借胡惟庸案废除丞相制度，权分六部，皇帝直接统领。"},{id:"cs-1203",module:"changshi",prompt:"清朝雍正时期设立的、标志着君主专制达到顶峰的机构是：",options:["内阁", "南书房", "军机处", "理藩院"],answer:2,explanation:"军机处设立于雍正年间，军机大臣跪受笔录，君主专制达到顶峰。"},{id:"cs-1204",module:"changshi",prompt:"郑和下西洋发生在哪个朝代？",options:["宋朝", "元朝", "明朝", "清朝"],answer:2,explanation:"1405—1433年郑和七次下西洋，最远到达非洲东海岸和红海沿岸。"},{id:"cs-1205",module:"changshi",prompt:"我国古代四大发明中，用于航海的是：",options:["造纸术", "印刷术", "指南针", "火药"],answer:2,explanation:"指南针应用于航海，大大促进了远洋航行，经阿拉伯人传入欧洲，为新航路开辟提供条件。"},{id:"cs-1206",module:"changshi",prompt:"鸦片战争爆发于哪一年？",options:["1839年", "1840年", "1842年", "1856年"],answer:1,explanation:"1840年英国发动鸦片战争，1842年清政府战败签订《南京条约》，中国开始沦为半殖民地半封建社会。"},{id:"cs-1207",module:"changshi",prompt:"太平天国运动的领导人是：",options:["洪秀全", "李自成", "张献忠", "义和团"],answer:0,explanation:"1851年洪秀全发动金田起义，建立太平天国，是规模最大的农民起义。"},{id:"cs-1208",module:"changshi",prompt:"戊戌变法发生在哪一年？",options:["1895年", "1898年", "1900年", "1901年"],answer:1,explanation:"1898年（农历戊戌年）光绪帝颁布《定国是诏》推行变法，历时103天后失败，史称百日维新。"},{id:"cs-1209",module:"changshi",prompt:"中国第一个资产阶级革命团体是：",options:["兴中会", "同盟会", "华兴会", "光复会"],answer:0,explanation:"1894年孙中山在檀香山创立兴中会，是中国第一个资产阶级革命团体；1905年同盟会是第一个全国性资产阶级革命政党。"},{id:"cs-1210",module:"changshi",prompt:"辛亥革命爆发的标志是：",options:["金田起义", "武昌起义", "南昌起义", "广州起义"],answer:1,explanation:"1911年10月10日武昌起义爆发，随后各省纷纷独立，推翻了清王朝统治。"},{id:"cs-1211",module:"changshi",prompt:"中国共产党成立的时间是：",options:["1919年7月", "1920年8月", "1921年7月", "1922年7月"],answer:2,explanation:"1921年7月23日中共一大在上海召开，后转移到浙江嘉兴南湖游船上，中国共产党成立。"},{id:"cs-1212",module:"changshi",prompt:"红军长征途中召开的、确立毛泽东领导地位的会议是：",options:["八七会议", "遵义会议", "瓦窑堡会议", "洛川会议"],answer:1,explanation:"1935年1月遵义会议确立了毛泽东在党中央和红军的领导地位，是党的历史上生死攸关的转折点。"},{id:"cs-1213",module:"changshi",prompt:"抗日战争全面爆发的标志是：",options:["九一八事变", "七七事变（卢沟桥事变）", "八一三事变", "西安事变"],answer:1,explanation:"1937年7月7日卢沟桥事变标志日本全面侵华，中国全民族抗战开始。"},{id:"cs-1214",module:"changshi",prompt:"抗战以来中国军队取得的第一个大胜利是：",options:["台儿庄战役", "平型关大捷", "百团大战", "淞沪会战"],answer:1,explanation:"1937年9月平型关大捷是全民族抗战以来中国军队取得的第一个重大胜利，打破了日军不可战胜的神话。"},{id:"cs-1215",module:"changshi",prompt:"日本宣布无条件投降的时间是：",options:["1945年8月15日", "1945年9月2日", "1945年10月1日", "1944年12月31日"],answer:0,explanation:"1945年8月15日日本天皇宣布无条件投降，9月2日签署投降书，抗战胜利。"},{id:"cs-1216",module:"changshi",prompt:"解放战争时期，揭开战略反攻序幕的事件是：",options:["辽沈战役", "刘邓大军千里跃进大别山", "淮海战役", "渡江战役"],answer:1,explanation:"1947年6月刘邓大军强渡黄河、千里跃进大别山，揭开战略反攻序幕。"},{id:"cs-1217",module:"changshi",prompt:"三大战役不包括：",options:["辽沈战役", "淮海战役", "平津战役", "渡江战役"],answer:3,explanation:"三大战役是辽沈、淮海、平津战役；渡江战役发生在三大战役之后。"},{id:"cs-1218",module:"changshi",prompt:"中国人民政治协商会议第一届全体会议召开于：",options:["1949年3月", "1949年9月", "1949年10月", "1950年1月"],answer:1,explanation:"1949年9月第一届政协会议在北平召开，通过了《共同纲领》，代行临时宪法职能。"},{id:"cs-1219",module:"changshi",prompt:"开辟新航路的航海家麦哲伦船队的贡献是：",options:["发现美洲", "环球航行", "到达印度", "发现好望角"],answer:1,explanation:"1519—1522年麦哲伦船队完成人类首次环球航行，证明了地圆说的正确。"},{id:"cs-1220",module:"changshi",prompt:"英国资产阶级革命推翻的制度是：",options:["共和制", "封建君主专制", "联邦制", "贵族制"],answer:1,explanation:"1640—1688年英国资产阶级革命推翻封建君主专制，1689年《权利法案》确立君主立宪制。"},{id:"cs-1221",module:"changshi",prompt:"美国独立战争爆发的标志是：",options:["波士顿倾茶事件", "莱克星顿枪声", "萨拉托加大捷", "约克镇战役"],answer:1,explanation:"1775年莱克星顿枪声打响美国独立战争第一枪，1776年《独立宣言》发表。"},{id:"cs-1222",module:"changshi",prompt:"法国大革命爆发的标志是：",options:["攻占巴士底狱", "处死国王", "热月政变", "雾月政变"],answer:0,explanation:"1789年7月14日巴黎人民攻占巴士底狱，法国大革命爆发，7月14日成为法国国庆日。"},{id:"cs-1223",module:"changshi",prompt:"第一次世界大战的导火索是：",options:["萨拉热窝事件", "凡尔登战役", "珍珠港事件", "慕尼黑阴谋"],answer:0,explanation:"1914年6月萨拉热窝事件（斐迪南大公遇刺）成为一战导火索。"},{id:"cs-1224",module:"changshi",prompt:"世界上第一个社会主义国家诞生于：",options:["巴黎公社", "俄国十月革命", "中国革命", "古巴革命"],answer:1,explanation:"1917年俄国十月革命胜利，建立了世界上第一个社会主义国家。"},{id:"cs-1225",module:"changshi",prompt:"联合国正式成立于：",options:["1944年", "1945年", "1946年", "1947年"],answer:1,explanation:"1945年10月24日《联合国宪章》生效，联合国正式成立，总部设在美国纽约。"},{id:"cs-1226",module:"changshi",prompt:"四书是指《大学》《中庸》《论语》和：",options:["《春秋》", "《孟子》", "《诗经》", "《周易》"],answer:1,explanation:"四书指《大学》《中庸》《论语》《孟子》，由朱熹编定；五经为诗、书、礼、易、春秋。"},{id:"cs-1227",module:"changshi",prompt:"我国古代十二时辰中，子时对应现在的：",options:["23时至1时", "1时至3时", "19时至21时", "11时至13时"],answer:0,explanation:"子时为23时至次日1时，午时为11时至13时。"},{id:"cs-1228",module:"changshi",prompt:"农历五月初五端午节的主要习俗是：",options:["登高", "赛龙舟、吃粽子", "赏月", "扫墓"],answer:1,explanation:"端午节为农历五月初五，习俗有赛龙舟、吃粽子、挂艾草等，相传为纪念屈原。"},{id:"cs-1229",module:"changshi",prompt:"我国古代科举制中，通过乡试的人称为：",options:["秀才", "举人", "贡士", "进士"],answer:1,explanation:"通过乡试者称举人，第一名称解元；通过会试者称贡士；殿试后为进士。"},{id:"cs-1230",module:"changshi",prompt:"《史记》的作者是：",options:["司马迁", "司马光", "班固", "陈寿"],answer:0,explanation:"《史记》为西汉司马迁所著，是我国第一部纪传体通史，鲁迅誉为史家之绝唱、无韵之离骚。"},{id:"cs-1231",module:"changshi",prompt:"书法史上被称为书圣的是：",options:["颜真卿", "王羲之", "柳公权", "欧阳询"],answer:1,explanation:"东晋王羲之被后世尊为书圣，代表作《兰亭序》被誉为天下第一行书。"},{id:"cs-1232",module:"changshi",prompt:"京剧脸谱中，红色一般象征：",options:["奸诈", "忠勇正义", "刚烈鲁莽", "阴险"],answer:1,explanation:"京剧脸谱红色象征忠勇正义（如关羽），白色多象征奸诈（如曹操），黑色象征刚正（如包拯）。"},{id:"cs-1233",module:"changshi",prompt:"我国古代六艺指的是：",options:["礼、乐、射、御、书、数", "诗、书、礼、易、乐、春秋", "琴、棋、书、画、诗、酒", "金、木、水、火、土"],answer:0,explanation:"六艺是周代贵族教育的内容：礼、乐、射、御、书、数。"},{id:"cs-1234",module:"changshi",prompt:"二十四节气中，白昼最长的节气是：",options:["春分", "夏至", "秋分", "冬至"],answer:1,explanation:"夏至日太阳直射北回归线，北半球白昼最长；冬至日白昼最短。"},{id:"cs-1235",module:"changshi",prompt:"我国古代对对方父亲的敬称是：",options:["令尊", "家父", "令郎", "舍弟"],answer:0,explanation:"令尊是对对方父亲的敬称，令堂是对对方母亲的敬称；家父、家母是对自己父母的谦称。"},{id:"cs-1236",module:"changshi",prompt:"中国传统婚礼中，三书六礼的六礼之首是：",options:["纳采", "问名", "纳吉", "亲迎"],answer:0,explanation:"六礼为纳采、问名、纳吉、纳征、请期、亲迎，纳采即提亲，是六礼之首。"},{id:"cs-1237",module:"changshi",prompt:"我国古代科举殿试后，进士及第者中一甲只取：",options:["一人", "三人", "十人", "百人"],answer:1,explanation:"殿试一甲只取三名：状元、榜眼、探花，赐进士及第。"},{id:"cs-1238",module:"changshi",prompt:"中华民族的图腾龙，在传统文化中象征：",options:["皇权与祥瑞", "战争", "丰收", "智慧"],answer:0,explanation:"龙是中华民族的图腾，象征皇权、祥瑞与民族精神，中国人自称龙的传人。"},{id:"cs-1239",module:"changshi",prompt:"我国古代把一夜分为五更，三更对应的时间是：",options:["19—21时", "21—23时", "23—1时", "1—3时"],answer:2,explanation:"一夜分五更，每更约两小时，三更为23时至1时，即子时，故有三更半夜之说。"},{id:"cs-1240",module:"changshi",prompt:"我国古代科举考试中，连中三元指的是：",options:["乡试、会试、殿试均得第一", "三次科举均落榜", "连过三关", "三年连中"],answer:0,explanation:"连中三元指在乡试（解元）、会试（会元）、殿试（状元）中均获第一名。"},{id:"cs-1241",module:"changshi",prompt:"我国传统建筑中，四合院通常坐北朝南，主要原因是：",options:["美观", "采光避风", "风水迷信", "防御"],answer:1,explanation:"我国位于北半球，坐北朝南利于采光取暖，同时避开冬季北风，符合宜居原则。"},{id:"cs-1242",module:"changshi",prompt:"我国古代乐器按制作材料分为八音，不包括：",options:["金", "石", "丝", "电"],answer:3,explanation:"八音指金、石、土、革、丝、木、匏、竹八类乐器制作材料，没有电。"},{id:"cs-1243",module:"changshi",prompt:"我国历史上唯一的女皇帝是：",options:["吕后", "武则天", "慈禧", "萧太后"],answer:1,explanation:"武则天是我国历史上唯一的女皇帝，建立武周政权，晚年还政于唐。"},{id:"cs-1244",module:"changshi",prompt:"西周礼乐制度的核心作用是：",options:["发展经济", "维护等级秩序", "繁荣文化", "选拔人才"],answer:1,explanation:"礼乐制度通过规范不同等级的礼仪用乐，维护西周的等级秩序和统治稳定。"},{id:"cs-1245",module:"changshi",prompt:"战国时期各国变法中影响最大的是：",options:["李悝变法", "吴起变法", "商鞅变法", "邹忌改革"],answer:2,explanation:"商鞅在秦国两次变法，废井田、开阡陌、奖励耕战、推行县制，使秦国成为战国后期最富强的国家。"},{id:"cs-1246",module:"changshi",prompt:"汉初为恢复经济采取的政策是：",options:["重征赋税", "休养生息", "盐铁官营", "均输平准"],answer:1,explanation:"汉初吸取秦亡教训，采取休养生息政策，轻徭薄赋，出现文景之治。"},{id:"cs-1247",module:"changshi",prompt:"东汉时期改进造纸术的是：",options:["张衡", "蔡伦", "毕昇", "沈括"],answer:1,explanation:"东汉蔡伦改进造纸术，用树皮、麻头等造纸，降低了成本，人称蔡侯纸。"},{id:"cs-1248",module:"changshi",prompt:"东晋南朝时期江南经济得以开发的主要原因是：",options:["气候变暖", "北方人口南迁带来劳动力和技术", "政策扶持", "对外贸易"],answer:1,explanation:"北方战乱，人口大量南迁，带去了先进的生产工具和技术，促进了江南开发。"},{id:"cs-1249",module:"changshi",prompt:"唐朝实行的选官制度是：",options:["察举制", "九品中正制", "科举制", "征辟制"],answer:2,explanation:"唐朝继承隋朝科举制并完善，设进士、明经等科，成为此后千年选官主要途径。"},{id:"cs-1250",module:"changshi",prompt:"唐朝出现的、被称为雕版印刷代表作的是：",options:["《金刚经》卷子", "《史记》刻本", "《资治通鉴》", "《永乐大典》"],answer:0,explanation:"唐朝雕版印刷术成熟，868年刻印的《金刚经》是现存最早的有明确纪年的雕版印刷品。"},{id:"cs-1251",module:"changshi",prompt:"北宋出现的、世界最早的纸币是：",options:["交子", "会子", "宝钞", "银票"],answer:0,explanation:"北宋前期四川地区出现的交子，是世界上最早的纸币。"},{id:"cs-1252",module:"changshi",prompt:"明朝郑和下西洋的目的是不包括：",options:["宣扬国威", "加强海外联系", "寻找建文帝（一说）", "殖民扩张"],answer:3,explanation:"郑和下西洋是和平交往，不以殖民扩张为目的，与后来西方航海性质不同。"},{id:"cs-1253",module:"changshi",prompt:"清朝前期巩固统一多民族国家的措施不包括：",options:["平定准噶尔", "设驻藏大臣", "签订《尼布楚条约》", "设内阁首辅"],answer:3,explanation:"内阁首辅是明朝制度；清朝通过平叛、设将军辖区和驻藏大臣、签订边界条约等巩固统一。"},{id:"cs-1254",module:"changshi",prompt:"第二次鸦片战争中焚毁圆明园的是：",options:["英国军队", "英法联军", "八国联军", "日本军队"],answer:1,explanation:"1860年英法联军攻入北京，劫掠并焚毁圆明园，是人类文明史上的浩劫。"},{id:"cs-1255",module:"changshi",prompt:"洋务运动中创办的第一个大型近代军事工业是：",options:["江南制造总局", "福州船政局", "安庆内军械所", "天津机器局"],answer:2,explanation:"1861年曾国藩创办的安庆内军械所是洋务派创办的第一个大型近代军事工业。"},{id:"cs-1256",module:"changshi",prompt:"中国近代第一所新式学堂是：",options:["京师大学堂", "京师同文馆", "福州船政学堂", "北洋水师学堂"],answer:1,explanation:"1862年设立的京师同文馆是中国近代第一所新式学堂，培养外语人才。"},{id:"cs-1257",module:"changshi",prompt:"中国同盟会的革命纲领被概括为：",options:["三民主义", "扶清灭洋", "民主科学", "实业救国"],answer:0,explanation:"同盟会纲领驱除鞑虏、恢复中华、创立民国、平均地权，孙中山概括为民族、民权、民生三民主义。"},{id:"cs-1258",module:"changshi",prompt:"新文化运动的基本内容是：",options:["提倡民主与科学，反对专制与迷信", "提倡国货", "扶清灭洋", "实业救国"],answer:0,explanation:"新文化运动提倡民主与科学，反对专制与迷信；提倡新道德，反对旧道德；提倡新文学，反对旧文学。"},{id:"cs-1259",module:"changshi",prompt:"中共二大最重要的贡献是：",options:["确立党的名称", "制定民主革命纲领", "确立武装斗争", "确立土地革命路线"],answer:1,explanation:"1922年中共二大制定了党的最高纲领和最低纲领（打倒军阀、推翻国际帝国主义压迫、统一中国为真正的民主共和国），第一次明确提出反帝反封建的民主革命纲领。"},{id:"cs-1260",module:"changshi",prompt:"西安事变和平解决的最重要意义是：",options:["张学良获释", "抗日民族统一战线初步形成", "国共合作正式形成", "红军改编"],answer:1,explanation:"1936年12月西安事变和平解决，十年内战基本结束，抗日民族统一战线初步形成。"},{id:"cs-1261",module:"changshi",prompt:"1938年李宗仁指挥的、抗战以来正面战场最大胜利的战役是：",options:["淞沪会战", "台儿庄战役", "武汉会战", "长沙会战"],answer:1,explanation:"台儿庄战役歼敌一万余人，是抗战以来正面战场取得的最大胜利。"},{id:"cs-1262",module:"changshi",prompt:"1940年八路军发动的、规模最大的主动出击日军的战役是：",options:["平型关大捷", "百团大战", "黄土岭战斗", "忻口会战"],answer:1,explanation:"1940年下半年彭德怀指挥八路军一百多个团发动百团大战，沉重打击了日军的囚笼政策。"},{id:"cs-1263",module:"changshi",prompt:"1945年国共重庆谈判达成的协议是：",options:["双十协定", "停战协定", "国内和平协定", "共同纲领"],answer:0,explanation:"1945年10月国共双方签订《双十协定》，确定和平建国的基本方针。"},{id:"cs-1264",module:"changshi",prompt:"1949年4月，人民解放军占领南京，标志着：",options:["抗战胜利", "统治中国22年的国民党政权覆灭", "三大战役结束", "新中国成立"],answer:1,explanation:"1949年4月23日人民解放军占领南京，宣告国民党在大陆22年统治的覆灭。"},{id:"cs-1265",module:"changshi",prompt:"1950年颁布的、彻底废除封建土地制度的法律文件是：",options:["《共同纲领》", "《中华人民共和国土地改革法》", "《五四宪法》", "《婚姻法》"],answer:1,explanation:"1950年《土地改革法》颁布，到1952年底土地改革基本完成，彻底废除了封建土地制度。"},{id:"cs-1266",module:"changshi",prompt:"文艺复兴时期创作《蒙娜丽莎》的画家是：",options:["米开朗琪罗", "达·芬奇", "拉斐尔", "提香"],answer:1,explanation:"达·芬奇是文艺复兴代表人物，代表作《蒙娜丽莎》《最后的晚餐》。"},{id:"cs-1267",module:"changshi",prompt:"英国工业革命中，使人类进入蒸汽时代的发明是：",options:["珍妮机", "改良蒸汽机", "火车", "轮船"],answer:1,explanation:"瓦特改良蒸汽机解决了动力问题，人类进入蒸汽时代，工厂制取代手工工场。"},{id:"cs-1268",module:"changshi",prompt:"美国1787年宪法确立的原则不包括：",options:["三权分立", "联邦制", "人民主权", "君主立宪"],answer:3,explanation:"美国1787年宪法确立三权分立、联邦制、人民主权等原则，是共和制国家，无君主。"},{id:"cs-1269",module:"changshi",prompt:"拿破仑颁布的、成为近代欧洲民法典范本的是：",options:["《拿破仑法典》（民法典）", "《人权宣言》", "《权利法案》", "《独立宣言》"],answer:0,explanation:"1804年《拿破仑法典》（法国民法典）确立了私有财产不可侵犯等原则，成为近代欧洲民法的范本。"},{id:"cs-1270",module:"changshi",prompt:"第一次世界大战后建立的国际组织是：",options:["联合国", "国际联盟", "世贸组织", "北约"],answer:1,explanation:"一战后1920年成立国际联盟，是第一个世界性国际政治组织，但未能阻止二战爆发。"},{id:"cs-1271",module:"changshi",prompt:"1929—1933年经济大危机的特点不包括：",options:["范围广", "时间长", "破坏大", "由战争直接引发"],answer:3,explanation:"大危机由生产过剩引发，不是战争直接引发；特点为范围广、时间长、破坏性大。"},{id:"cs-1272",module:"changshi",prompt:"罗斯福新政的中心措施是：",options:["整顿银行业", "对工业的调整（《全国工业复兴法》）", "兴办公共工程", "农业补贴"],answer:1,explanation:"罗斯福新政的中心措施是对工业的调整，颁布《全国工业复兴法》，加强国家对经济的干预。"},{id:"cs-1273",module:"changshi",prompt:"二战中使美国正式参战的事件是：",options:["敦刻尔克撤退", "珍珠港事件", "斯大林格勒战役", "阿拉曼战役"],answer:1,explanation:"1941年12月7日日本偷袭珍珠港，太平洋战争爆发，美国正式参战，二战达到最大规模。"},{id:"cs-1274",module:"changshi",prompt:"1942年《联合国家宣言》签署的最重要意义是：",options:["成立联合国", "世界反法西斯同盟正式形成", "结束一战", "建立北约"],answer:1,explanation:"1942年1月26国签署《联合国家宣言》，世界反法西斯同盟正式形成，为战胜法西斯奠定基础。"},{id:"cs-1275",module:"changshi",prompt:"第二次世界大战欧洲战场结束的标志是：",options:["诺曼底登陆", "德国无条件投降", "柏林战役开始", "雅尔塔会议"],answer:1,explanation:"1945年5月8日德国无条件投降，欧洲战事结束；9月2日日本投降，二战最终结束。"},{id:"cs-1276",module:"changshi",prompt:"我国古代科举考试中，会试在哪个城市举行？",options:["南京", "北京", "杭州", "洛阳"],answer:1,explanation:"明清时期会试在京师（北京）举行，由礼部主持，又称礼闱。"},{id:"cs-1277",module:"changshi",prompt:"我国传统节日中，与嫦娥奔月传说相关的是：",options:["元宵节", "清明节", "中秋节", "重阳节"],answer:2,explanation:"中秋节为农历八月十五，与嫦娥奔月、吴刚伐桂等传说相关，习俗是赏月吃月饼。"},{id:"cs-1278",module:"changshi",prompt:"我国古代年龄称谓中，弱冠指的是：",options:["八岁", "十五岁", "二十岁", "三十岁"],answer:2,explanation:"男子二十岁称弱冠，行冠礼；三十而立，四十不惑，五十知天命。"},{id:"cs-1279",module:"changshi",prompt:"我国古代书法五体不包括：",options:["篆书", "隶书", "楷书", "拉丁文"],answer:3,explanation:"书法五体为篆、隶、楷、行、草，拉丁文是西方文字。"},{id:"cs-1280",module:"changshi",prompt:"我国古代四大书院不包括：",options:["岳麓书院", "白鹿洞书院", "嵩阳书院", "岳飞书院"],answer:3,explanation:"四大书院为岳麓、白鹿洞、嵩阳、应天书院，没有岳飞书院。"},{id:"cs-1281",module:"changshi",prompt:"我国古代把一天分为十二个时辰，一个时辰等于：",options:["半小时", "一小时", "两小时", "四小时"],answer:2,explanation:"一个时辰等于两小时，一天十二时辰。"},{id:"cs-1282",module:"changshi",prompt:"我国传统戏曲中，被称为国粹的是：",options:["越剧", "黄梅戏", "京剧", "豫剧"],answer:2,explanation:"京剧被视为中国戏曲的代表，称为国粹，形成于清朝道光年间的北京。"},{id:"cs-1283",module:"changshi",prompt:"我国古代数学成就中，祖冲之的贡献是：",options:["发明算盘", "将圆周率精确到小数点后七位", "著《九章算术》", "发明勾股定理"],answer:1,explanation:"南朝祖冲之将圆周率精确到3.1415926—3.1415927之间，领先世界近千年。"},{id:"cs-1284",module:"changshi",prompt:"我国古代建筑中，屋脊上的吻兽主要作用是：",options:["装饰与象征辟邪防火", "承重", "排水", "通风"],answer:0,explanation:"吻兽既有装饰作用，又象征辟邪防火，体现古代建筑艺术与文化内涵。"},{id:"cs-1285",module:"changshi",prompt:"我国古代对教师的尊称不包括：",options:["夫子", "先生", "园丁", "西席"],answer:2,explanation:"夫子、先生、西席、绛帐都是对教师的尊称；园丁是现代比喻，不是古代尊称。"},{id:"cs-1286",module:"changshi",prompt:"我国古代医学中，被尊为医圣的是：",options:["扁鹊", "华佗", "张仲景", "李时珍"],answer:2,explanation:"东汉张仲景著《伤寒杂病论》，被尊为医圣；华佗为外科圣手，李时珍著《本草纲目》。"},{id:"cs-1287",module:"changshi",prompt:"我国古代天文仪器中，用于观测天体坐标的是：",options:["浑仪", "日晷", "漏刻", "司南"],answer:0,explanation:"浑仪用于测定天体坐标；日晷和漏刻用于计时，司南用于指示方向。"},{id:"cs-1288",module:"changshi",prompt:"我国古代科举制度中，殿试的组织者是：",options:["礼部", "吏部", "皇帝亲自主持", "翰林院"],answer:2,explanation:"殿试由皇帝亲自主持，故称天子门生，是科举最高一级考试。"},{id:"cs-1289",module:"changshi",prompt:"我国传统建筑中，用于分隔室内空间的可移动屏障称为：",options:["屏风", "门楣", "斗拱", "藻井"],answer:0,explanation:"屏风是室内可移动的分隔屏障，兼具实用与装饰功能；斗拱是承重构件，藻井是天花装饰。"},{id:"cs-1290",module:"changshi",prompt:"我国古代把朋友按交情分为八拜之交，八拜之交不包括：",options:["知音之交", "刎颈之交", "忘年之交", "酒肉之交"],answer:3,explanation:"八拜之交指知音、刎颈、忘年、生死、布衣、杵臼、胶漆、鸡黍之交等高洁交情，酒肉之交不在其中。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-1291",module:"changshi",prompt:"我国自行研制的载人飞船系列是：",options:["嫦娥系列", "神舟系列", "天问系列", "北斗系列"],answer:1,explanation:"神舟系列是我国载人航天飞船；嫦娥是探月工程，天问是行星探测，北斗是卫星导航系统。"},{id:"cs-1292",module:"changshi",prompt:"世界上第一台电子计算机诞生于：",options:["1946年", "1956年", "1966年", "1936年"],answer:0,explanation:"1946年美国宾夕法尼亚大学研制出ENIAC，是世界上第一台通用电子计算机。"},{id:"cs-1293",module:"changshi",prompt:"我国首位进入太空的航天员是：",options:["翟志刚", "杨利伟", "聂海胜", "刘洋"],answer:1,explanation:"2003年10月杨利伟乘神舟五号进入太空，是我国首位进入太空的航天员。"},{id:"cs-1294",module:"changshi",prompt:"人类基因组计划的主要任务是：",options:["克隆人类", "测定人类基因组全部DNA序列", "治疗癌症", "编辑基因"],answer:1,explanation:"人类基因组计划旨在测定人类基因组约30亿个碱基对的序列，破译人类遗传信息。"},{id:"cs-1295",module:"changshi",prompt:"5G通信技术相比4G最突出的特点是：",options:["仅通话更清晰", "高带宽、低时延、大连接", "成本更高", "覆盖更广"],answer:1,explanation:"5G具有高速率、低时延、海量连接的特点，支撑物联网、自动驾驶等应用。"},{id:"cs-1296",module:"changshi",prompt:"我国自主建设的全球卫星导航系统是：",options:["GPS", "北斗", "格洛纳斯", "伽利略"],answer:1,explanation:"北斗卫星导航系统是我国自主建设的全球卫星导航系统，2020年完成全球组网。"},{id:"cs-1297",module:"changshi",prompt:"人工智能的三大核心基础不包括：",options:["算法", "算力", "数据", "情感"],answer:3,explanation:"人工智能三要素是算法、算力、数据；机器没有真实情感。"},{id:"cs-1298",module:"changshi",prompt:"量子通信的最大优势是：",options:["传输速度快", "通信安全性高，原理上不可窃听", "成本低", "距离远"],answer:1,explanation:"量子通信基于量子态，窃听会改变量子态而被发现，原理上保证了通信安全。"},{id:"cs-1299",module:"changshi",prompt:"我国天眼FAST射电望远镜的主要用途是：",options:["观测宇宙射电信号", "发射卫星", "气象预报", "导航定位"],answer:0,explanation:"500米口径球面射电望远镜FAST用于接收宇宙射电信号，主要科学目标包括脉冲星搜寻等。"},{id:"cs-1300",module:"changshi",prompt:"新能源汽车中，目前市场占比最大的是：",options:["纯电动汽车", "氢燃料电池车", "太阳能车", "甲醇车"],answer:0,explanation:"纯电动汽车是目前新能源汽车市场的主流类型，锂电池为主要动力来源。"},{id:"cs-1301",module:"changshi",prompt:"3D打印技术属于：",options:["增材制造", "减材制造", "等材制造", "铸造工艺"],answer:0,explanation:"3D打印通过逐层堆积材料成型，属于增材制造技术。"},{id:"cs-1302",module:"changshi",prompt:"我国探月工程嫦娥五号的主要任务是：",options:["月球车巡视", "月球采样返回", "绕月成像", "载人登月"],answer:1,explanation:"嫦娥五号实现了我国首次月球采样返回，带回约1731克月壤。"},{id:"cs-1303",module:"changshi",prompt:"北斗卫星导航系统提供的基本服务不包括：",options:["定位", "导航", "授时", "天气预报"],answer:3,explanation:"北斗系统提供定位、导航、授时及短报文通信服务，不提供天气预报。"},{id:"cs-1304",module:"changshi",prompt:"计算机中，1GB等于：",options:["1024KB", "1024MB", "1024TB", "100MB"],answer:1,explanation:"1GB=1024MB，1MB=1024KB，存储单位按二进制换算。"},{id:"cs-1305",module:"changshi",prompt:"世界上首颗量子科学实验卫星是：",options:["墨子号", "悟空号", "慧眼号", "羲和号"],answer:0,explanation:"2016年发射的墨子号是全球首颗量子科学实验卫星，实现了星地量子通信。"},{id:"cs-1306",module:"changshi",prompt:"我国载人空间站的名称是：",options:["天宫", "天问", "祝融", "羲和"],answer:0,explanation:"中国空间站名为天宫，由天和核心舱、问天实验舱、梦天实验舱组成。"},{id:"cs-1307",module:"changshi",prompt:"克隆羊多莉诞生于哪个国家？",options:["美国", "英国", "日本", "中国"],answer:1,explanation:"1996年英国罗斯林研究所培育出克隆羊多莉，是世界上第一只克隆哺乳动物。"},{id:"cs-1308",module:"changshi",prompt:"疫苗的作用原理是：",options:["直接杀死病原体", "刺激机体产生特异性免疫", "补充营养", "抗生素作用"],answer:1,explanation:"疫苗通过接种抗原刺激机体产生抗体和免疫记忆，从而获得对特定传染病的免疫力。"},{id:"cs-1309",module:"changshi",prompt:"我国首艘国产航空母舰是：",options:["辽宁舰", "山东舰", "福建舰", "南昌舰"],answer:1,explanation:"山东舰是我国首艘国产航母，2019年入列；辽宁舰由旧舰改装；福建舰为第三艘，采用电磁弹射。"},{id:"cs-1310",module:"changshi",prompt:"计算机病毒的本质是：",options:["生物病毒", "一段特殊的计算机程序", "硬件故障", "网络攻击设备"],answer:1,explanation:"计算机病毒是编制者在计算机程序中插入的破坏计算机功能或数据的代码，能自我复制。"},{id:"cs-1311",module:"changshi",prompt:"我国陆地面积约：",options:["960万平方公里", "860万平方公里", "1060万平方公里", "1260万平方公里"],answer:0,explanation:"我国陆地面积约960万平方公里，居世界第三位，仅次于俄罗斯和加拿大。"},{id:"cs-1312",module:"changshi",prompt:"我国最大的岛屿是：",options:["海南岛", "台湾岛", "崇明岛", "长兴岛"],answer:1,explanation:"台湾岛是我国面积最大的岛屿，面积约3.6万平方公里。"},{id:"cs-1313",module:"changshi",prompt:"我国气候最重要的特征是：",options:["全年高温", "季风气候显著，气候类型多样", "全年多雨", "海洋性气候"],answer:1,explanation:"我国东部季风气候显著，南北跨多个温度带，气候类型多样，雨热同期。"},{id:"cs-1314",module:"changshi",prompt:"世界最高峰珠穆朗玛峰的最新高程约为：",options:["8848米", "8848.86米", "8900米", "8760米"],answer:1,explanation:"2020年中尼联合公布珠峰最新高程为8848.86米。"},{id:"cs-1315",module:"changshi",prompt:"我国最大的瀑布是：",options:["壶口瀑布", "黄果树瀑布", "庐山瀑布", "德天瀑布"],answer:1,explanation:"黄果树瀑布位于贵州省，是我国最大的瀑布，落差约77.8米。"},{id:"cs-1316",module:"changshi",prompt:"我国四大高原不包括：",options:["青藏高原", "内蒙古高原", "黄土高原", "东北平原"],answer:3,explanation:"四大高原为青藏、内蒙古、黄土、云贵高原；东北平原是平原。"},{id:"cs-1317",module:"changshi",prompt:"我国南北方分界线是：",options:["长江", "秦岭—淮河一线", "黄河", "南岭"],answer:1,explanation:"秦岭—淮河一线是我国南北方的地理分界线，也是800毫米等降水量线、1月0℃等温线经过地。"},{id:"cs-1318",module:"changshi",prompt:"世界最长的河流是：",options:["长江", "尼罗河", "亚马逊河", "密西西比河"],answer:1,explanation:"尼罗河全长约6650公里，是世界最长的河流；长江为世界第三长河。"},{id:"cs-1319",module:"changshi",prompt:"我国最大的城市群位于：",options:["长三角", "珠三角", "京津冀", "成渝"],answer:0,explanation:"长三角城市群是我国规模最大、经济最发达的城市群，以上海为中心。"},{id:"cs-1320",module:"changshi",prompt:"我国少数民族种类最多的省份是：",options:["云南", "广西", "贵州", "新疆"],answer:0,explanation:"云南省是我国少数民族种类最多的省份，有25个世居少数民族。"},{id:"cs-1321",module:"changshi",prompt:"我国五大淡水湖不包括：",options:["鄱阳湖", "洞庭湖", "太湖", "青海湖"],answer:3,explanation:"五大淡水湖为鄱阳湖、洞庭湖、太湖、洪泽湖、巢湖；青海湖是咸水湖。"},{id:"cs-1322",module:"changshi",prompt:"我国季风区与非季风区的分界山脉不包括：",options:["大兴安岭", "阴山", "贺兰山", "武夷山"],answer:3,explanation:"季风区与非季风区分界线为大兴安岭—阴山—贺兰山—巴颜喀拉山—冈底斯山；武夷山不在其中。"},{id:"cs-1323",module:"changshi",prompt:"我国地势第二、三级阶梯的分界山脉不包括：",options:["大兴安岭", "太行山", "巫山", "昆仑山"],answer:3,explanation:"二三级阶梯分界为大兴安岭—太行山—巫山—雪峰山；昆仑山是一二级阶梯分界。"},{id:"cs-1324",module:"changshi",prompt:"我国冬季气温分布特点是：",options:["全国普遍高温", "南北温差大，越往北气温越低", "南北温差小", "南方比北方冷"],answer:1,explanation:"我国冬季南北温差大，南方温暖，北方寒冷，越往北气温越低。"},{id:"cs-1325",module:"changshi",prompt:"我国河流中被称为黄金水道的是：",options:["长江", "黄河", "珠江", "京杭运河"],answer:0,explanation:"长江航运价值高，干流通航里程长，运量占全国内河运输大部分，被称为黄金水道。"},{id:"cs-1326",module:"changshi",prompt:"我国土地资源的基本国情是：",options:["人多地少", "地多人少", "人地平衡", "全部可耕"],answer:0,explanation:"我国土地资源的基本国情是人多地少，人均耕地面积远低于世界平均水平。"},{id:"cs-1327",module:"changshi",prompt:"我国跨纬度最广的省级行政区是：",options:["新疆", "海南", "内蒙古", "黑龙江"],answer:1,explanation:"海南省管辖海域辽阔，跨纬度最广；新疆是面积最大、跨经度最广的是内蒙古。"},{id:"cs-1328",module:"changshi",prompt:"我国唯一内流大运河与世界文化遗产兼具的是：",options:["京杭大运河", "灵渠", "都江堰", "郑国渠"],answer:0,explanation:"京杭大运河是世界上里程最长、工程最大的古代运河，2014年列入世界文化遗产。"},{id:"cs-1329",module:"changshi",prompt:"我国最大的半岛是：",options:["辽东半岛", "山东半岛", "雷州半岛", "旅顺半岛"],answer:1,explanation:"山东半岛是我国最大的半岛，伸入渤海与黄海之间。"},{id:"cs-1330",module:"changshi",prompt:"我国四大海域中，最浅的是：",options:["渤海", "黄海", "东海", "南海"],answer:0,explanation:"渤海是我国的内海，平均深度最浅，约18米。"},{id:"cs-1331",module:"changshi",prompt:"我国唯一地跨热带、亚热带、温带三个气候带的省份是：",options:["云南", "海南", "广东", "台湾"],answer:0,explanation:"云南省地形复杂，气候垂直差异显著，兼有热带、亚热带、温带等多种气候类型。"},{id:"cs-1332",module:"changshi",prompt:"我国社会主义市场经济体制的所有制基础是：",options:["计划经济", "公有制为主体、多种所有制经济共同发展", "完全私有制", "国有经济一统"],answer:1,explanation:"公有制为主体、多种所有制经济共同发展是我国社会主义市场经济体制的所有制基础。"},{id:"cs-1333",module:"changshi",prompt:"通货膨胀的主要表现是：",options:["物价总水平持续上涨", "物价下跌", "经济停滞", "失业增加"],answer:0,explanation:"通货膨胀指货币供给超过需求，物价总水平持续、普遍上涨的经济现象。"},{id:"cs-1334",module:"changshi",prompt:"市场经济中，资源配置的主要手段是：",options:["计划指令", "价格机制", "行政命令", "道德约束"],answer:1,explanation:"市场经济通过价格、供求、竞争等市场机制实现资源配置，价格是核心信号。"},{id:"cs-1335",module:"changshi",prompt:"我国中央银行的主要职能是：",options:["商业银行存贷款", "制定和执行货币政策，维护金融稳定", "直接经营企业", "征收税收"],answer:1,explanation:"中国人民银行是我国的中央银行，负责制定和执行货币政策，维护金融稳定，不直接办理个人存贷款。"},{id:"cs-1336",module:"changshi",prompt:"恩格尔系数是指：",options:["食品支出占消费总支出的比重", "住房支出占比", "教育支出占比", "储蓄占比"],answer:0,explanation:"恩格尔系数是食品支出占消费总支出的比重，系数越低通常说明生活水平越高。"},{id:"cs-1337",module:"changshi",prompt:"我国的基本经济制度不包括：",options:["公有制为主体、多种所有制经济共同发展", "按劳分配为主体、多种分配方式并存", "社会主义市场经济体制", "完全自由放任的市场"],answer:3,explanation:"我国基本经济制度包括公有制为主体多种所有制共同发展、按劳分配为主体多种分配方式并存、社会主义市场经济体制，不包括完全自由放任。"},{id:"cs-1338",module:"changshi",prompt:"我国财政收入的最主要来源是：",options:["税收", "国企利润", "国债", "行政收费"],answer:0,explanation:"税收是我国财政收入的最主要来源，占财政收入的大部分。"},{id:"cs-1339",module:"changshi",prompt:"供给侧结构性改革的重点不包括：",options:["去产能", "去库存", "去杠杆", "增加行政干预"],answer:3,explanation:"供给侧结构性改革重点为去产能、去库存、去杠杆、降成本、补短板，不是增加行政干预。"},{id:"cs-1340",module:"changshi",prompt:"基尼系数衡量的是：",options:["收入分配公平程度", "物价水平", "经济增长速度", "失业率"],answer:0,explanation:"基尼系数介于0—1之间，数值越大表示收入分配差距越大，通常0.4为警戒线。"},{id:"cs-1341",module:"changshi",prompt:"我国对外开放的基本格局是：",options:["全方位、多层次、宽领域", "仅沿海开放", "仅对发达国家开放", "封闭半封闭"],answer:0,explanation:"我国形成了全方位、多层次、宽领域的对外开放格局，包括自贸区、一带一路等。"},{id:"cs-1342",module:"changshi",prompt:"通货膨胀时期，央行通常采取的货币政策是：",options:["降息降准", "加息提准", "增加货币发行", "降低利率"],answer:1,explanation:"通胀时期央行通常加息、提高存款准备金率，收紧流动性，抑制物价上涨。"},{id:"cs-1343",module:"changshi",prompt:"通货紧缩的主要表现是：",options:["物价持续下跌，货币购买力上升", "物价上涨", "经济过热", "就业增加"],answer:0,explanation:"通货紧缩指货币供应量少于流通需要，物价持续下跌，往往伴随经济衰退风险。"},{id:"cs-1344",module:"changshi",prompt:"市场经济的基本规律是：",options:["价值规律", "剩余价值规律", "供求规律", "竞争规律"],answer:0,explanation:"价值规律是市场经济的基本规律，商品交换以价值量为基础，实行等价交换。"},{id:"cs-1345",module:"changshi",prompt:"我国货币政策的目标是：",options:["保持币值稳定，并以此促进经济增长", "追求高通胀", "控制财政赤字", "调节外贸"],answer:0,explanation:"我国货币政策的目标是保持货币币值的稳定，并以此促进经济增长。"},{id:"cs-1346",module:"changshi",prompt:"财政政策与货币政策的区别在于：",options:["财政政策由政府主导，货币政策由央行主导", "二者相同", "财政政策管利率", "货币政策管税收"],answer:0,explanation:"财政政策通过税收、政府支出调节经济，由政府主导；货币政策通过利率、货币供应量调节，由央行执行。"},{id:"cs-1347",module:"changshi",prompt:"世界贸易组织（WTO）的核心职能是：",options:["制定国际贸易规则，解决贸易争端", "发行世界货币", "管理各国财政", "制定各国税法"],answer:0,explanation:"WTO负责制定和监督执行国际贸易规则，为成员提供贸易争端解决机制。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-1348",module:"changshi",prompt:"马克思主义哲学的核心是：",options:["辩证唯物主义和历史唯物主义", "形而上学", "唯心主义", "不可知论"],answer:0,explanation:"马克思主义哲学即辩证唯物主义和历史唯物主义，是科学的世界观和方法论。"},{id:"cs-1349",module:"changshi",prompt:"唯物辩证法的总特征是：",options:["联系的观点和发展的观点", "矛盾的观点", "实践的观点", "群众观点"],answer:0,explanation:"联系和发展是唯物辩证法的总特征；矛盾学说是其核心和实质。"},{id:"cs-1350",module:"changshi",prompt:"矛盾的特殊性要求我们：",options:["具体问题具体分析", "一刀切", "照搬经验", "平均用力"],answer:0,explanation:"矛盾特殊性要求具体问题具体分析，这是马克思主义活的灵魂。"},{id:"cs-1351",module:"changshi",prompt:"我国的国家性质是：",options:["人民民主专政的社会主义国家", "资本主义国家", "联邦制国家", "君主立宪制国家"],answer:0,explanation:"我国宪法规定，中华人民共和国是工人阶级领导的、以工农联盟为基础的人民民主专政的社会主义国家。"},{id:"cs-1352",module:"changshi",prompt:"我国的基本经济制度中，分配制度是：",options:["按劳分配为主体、多种分配方式并存", "按需分配", "平均分配", "按资分配"],answer:0,explanation:"我国坚持按劳分配为主体、多种分配方式并存的分配制度，由生产力水平和所有制结构决定。"},{id:"cs-1353",module:"changshi",prompt:"中国共产党的最大政治优势是：",options:["密切联系群众", "武装斗争", "统一战线", "思想建设"],answer:0,explanation:"中国共产党的最大政治优势是密切联系群众，执政后的最大危险是脱离群众。"},{id:"cs-1354",module:"changshi",prompt:"党的思想路线的核心是：",options:["实事求是", "群众路线", "独立自主", "改革开放"],answer:0,explanation:"党的思想路线是一切从实际出发，理论联系实际，实事求是，在实践中检验真理和发展真理，核心是实事求是。"},{id:"cs-1355",module:"changshi",prompt:"我国社会主要矛盾已经转化为：",options:["人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾", "人民日益增长的物质文化需要同落后的社会生产之间的矛盾", "阶级矛盾", "生产力与生产关系的矛盾"],answer:0,explanation:"党的十九大指出，我国社会主要矛盾已转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。"},{id:"cs-1356",module:"changshi",prompt:"四个自信的内容不包括：",options:["道路自信", "理论自信", "制度自信", "军事自信"],answer:3,explanation:"四个自信指道路自信、理论自信、制度自信、文化自信，没有军事自信。"},{id:"cs-1357",module:"changshi",prompt:"四个全面战略布局不包括：",options:["全面建设社会主义现代化国家", "全面深化改革", "全面依法治国", "全面对外开放"],answer:3,explanation:"四个全面是全面建设社会主义现代化国家、全面深化改革、全面依法治国、全面从严治党。"},{id:"cs-1358",module:"changshi",prompt:"四个意识的内容是：",options:["政治意识、大局意识、核心意识、看齐意识", "创新意识、协调意识、绿色意识、开放意识", "改革意识、发展意识、稳定意识、和谐意识", "道路意识、理论意识、制度意识、文化意识"],answer:0,explanation:"四个意识指政治意识、大局意识、核心意识、看齐意识，要求全党自觉维护党中央权威和集中统一领导。"},{id:"cs-1359",module:"changshi",prompt:"两个维护的内容是：",options:["坚决维护习近平总书记党中央的核心、全党的核心地位，坚决维护党中央权威和集中统一领导", "维护国家主权和领土完整", "维护人民利益", "维护社会稳定"],answer:0,explanation:"两个维护是坚决维护习近平总书记党中央的核心、全党的核心地位，坚决维护党中央权威和集中统一领导。"},{id:"cs-1360",module:"changshi",prompt:"中国梦的本质是：",options:["国家富强、民族振兴、人民幸福", "经济发展、社会和谐、文化繁荣", "政治清明、社会公正", "军事强大"],answer:0,explanation:"中国梦的本质是国家富强、民族振兴、人民幸福。"},{id:"cs-1361",module:"changshi",prompt:"一国两制的前提和基础是：",options:["一个中国", "两种制度", "高度自治", "港人治港"],answer:0,explanation:"一个中国是一国两制的前提和基础，坚持一个中国原则是两岸关系和平发展的政治基础。"},{id:"cs-1362",module:"changshi",prompt:"我国处理民族关系的基本原则是：",options:["民族平等、民族团结、各民族共同繁荣", "民族自治", "民族融合", "民族同化"],answer:0,explanation:"我国处理民族关系的基本原则是民族平等、民族团结和各民族共同繁荣。"},{id:"cs-1363",module:"changshi",prompt:"公文的主要种类不包括：",options:["决议、决定", "命令、公报", "通知、通报", "小说、散文"],answer:3,explanation:"法定公文种类包括决议、决定、命令、公报、公告、通告、意见、通知、通报、报告、请示、批复、议案、函、纪要，小说散文不是公文。"},{id:"cs-1364",module:"changshi",prompt:"公文写作的基本要求不包括：",options:["准确、简洁、庄重、规范", "使用文学化修辞", "符合行文规则", "格式规范"],answer:1,explanation:"公文写作要求准确、简洁、庄重、规范，不用文学化修辞和夸张手法。"},{id:"cs-1365",module:"changshi",prompt:"请示的行文规则是：",options:["一文一事", "多文一事", "越级行文", "多头主送"],answer:0,explanation:"请示应一文一事，主送一个主管机关，不得多头主送，一般不得越级行文。"},{id:"cs-1366",module:"changshi",prompt:"报告与请示的区别在于：",options:["报告不需要上级答复，请示需要答复", "二者相同", "报告需要答复", "请示不需要答复"],answer:0,explanation:"报告是向上级汇报工作、反映情况，不要求答复；请示是请求指示、批准，需要上级答复。"},{id:"cs-1367",module:"changshi",prompt:"公文的成文日期以什么为准？",options:["负责人签发日期", "印制日期", "会议通过日期（经会议讨论通过的）或负责人签发日期", "起草日期"],answer:2,explanation:"公文成文日期以会议通过或者发文机关负责人签发的日期为准，用阿拉伯数字写全年月日。"},{id:"cs-1368",module:"changshi",prompt:"管理学中，管理的四大基本职能是：",options:["计划、组织、领导、控制", "决策、执行、监督、反馈", "用人、理财、办事、议事", "预测、决策、计划、实施"],answer:0,explanation:"管理的基本职能包括计划、组织、领导、控制，贯穿管理全过程。"},{id:"cs-1369",module:"changshi",prompt:"马斯洛需求层次理论的最高层次需求是：",options:["生理需求", "安全需求", "尊重需求", "自我实现需求"],answer:3,explanation:"马斯洛将人的需求分为生理、安全、社交、尊重、自我实现五个层次，自我实现是最高层次。"},{id:"cs-1370",module:"changshi",prompt:"公共管理的核心对象是：",options:["公共事务", "私人事务", "企业利润", "个人利益"],answer:0,explanation:"公共管理以公共事务为对象，以公共利益为目标，由政府等公共组织承担主要责任。"},{id:"cs-1371",module:"changshi",prompt:"政府职能转变的方向是：",options:["建设服务型政府", "扩大审批", "强化管制", "包办一切"],answer:0,explanation:"我国政府职能转变的方向是简政放权、放管结合、优化服务，建设服务型政府。"},{id:"cs-1372",module:"changshi",prompt:"行政决策程序的第一步是：",options:["发现问题，确定目标", "拟定方案", "评估选择", "实施反馈"],answer:0,explanation:"行政决策的一般程序：发现问题、确定目标，拟定方案，评估选择方案，实施并反馈调整。"},{id:"cs-1373",module:"changshi",prompt:"公共政策执行的核心环节是：",options:["政策宣传与分解落实", "政策制定", "政策评估", "政策终结"],answer:0,explanation:"政策执行是把政策目标转化为现实的过程，核心环节包括宣传、分解、落实、监督等。"},{id:"cs-1374",module:"changshi",prompt:"公务员的处分种类不包括：",options:["警告", "记过", "降级", "罚款"],answer:3,explanation:"公务员处分包括警告、记过、记大过、降级、撤职、开除，不包括罚款。"},{id:"cs-1375",module:"changshi",prompt:"我国公务员制度的特点不包括：",options:["坚持党管干部原则", "德才兼备的用人标准", "政治中立", "服务人民"],answer:2,explanation:"我国公务员制度坚持党管干部、德才兼备、服务人民，不实行西方的政治中立。"},{id:"cs-1376",module:"changshi",prompt:"事业单位人事管理的基本制度是：",options:["聘用制", "终身制", "世袭制", "委任制"],answer:0,explanation:"事业单位与工作人员签订聘用合同，实行聘用制，是人事管理的基本制度。"},{id:"cs-1377",module:"changshi",prompt:"基层群众自治制度的内容不包括：",options:["村民委员会", "居民委员会", "职工代表大会", "国务院"],answer:3,explanation:"基层群众自治制度包括村委会、居委会、职工代表大会等，国务院是最高国家行政机关。"});
